const BOOK={"id":"science-5-part-1","title":"العلوم للصف الخامس · الجزء الأول","source":"https://www.edunet.bh/e_content/level_1/stage_5/subject_ID_5/Part_1/e_books/SCGr5SB/SCGr5SB/files/SCGr5SB2026.pdf","units":[{"id":"classification","title":"تصنيف المخلوقات الحية","lessons":[{"id":"levels","title":"مستويات تصنيف المخلوقات الحية","start":12,"end":21,"terms":["classification","kingdom","phylum","class","order","family","genus","species","plants","animals","vertebrates","invertebrates","fungi","bacteria","protists","vascular","nonvascular","cell","unicellular","multicellular","scientific-name","sponges","cnidarians","flatworms","roundworms","annelids","molluscs","arthropods","echinoderms","fish","amphibians","reptiles","birds","mammals","seed-plants","seedless","gymnosperms","angiosperms","archaea","true-bacteria","virus"]},{"id":"plants","title":"النباتات","start":22,"end":32,"terms":["root","root-hairs","taproot","fibrous","stem","xylem","phloem","leaf","photosynthesis","stomata","transpiration","root-cap","epidermis","cortex","vascular-tissue","spreading-roots","aerial-roots","prop-roots","soft-stem","woody-stem","cambium","annual-rings","chlorophyll","chloroplast","guard-cells","leaf-vein","waxy-layer","starch"]}]},{"id":"matter","title":"أنواع المادة","lessons":[{"id":"elements","title":"العناصر","start":36,"end":45,"terms":["matter","element","atom","atomic-nucleus","proton","neutron","electron","atomic-number","molecule","chemical-formula","element-symbol","periodic-table","period","group"]},{"id":"metals","title":"الفلزات واللافلزات وأشباه الفلزات","start":46,"end":54,"terms":["metal","nonmetal","metalloid","malleability","ductility","corrosion","conductor","semiconductor","insulator","noble-gases"]}]},{"id":"changes","title":"التغيرات الفيزيائية والكيميائية للمادة","lessons":[{"id":"states","title":"تغيرات حالة المادة","start":58,"end":65,"terms":["physical-change","solid","liquid","gas","melting","evaporation","condensation","freezing","sublimation","melting-point","boiling-point","freezing-point","thermal-expansion","thermal-contraction","heat","density","boiling"]},{"id":"compounds","title":"المركبات والتغيرات الكيميائية","start":66,"end":76,"terms":["compound","chemical-change","reactants","products","chemical-equation","mass-conservation","precipitate","rust","tarnish","respiration"]}]},{"id":"reproduction","title":"الآباء والأبناء","lessons":[{"id":"reproduction","title":"التكاثر","start":80,"end":87,"terms":["reproduction","heredity","inherited-trait","gamete","sperm","ovum","sexual","fertilization","asexual","division","budding","vegetative","runner"]},{"id":"life-cycles","title":"دورات الحياة","start":88,"end":100,"terms":["life-cycle","metamorphosis","complete-metamorphosis","larva","pupa","incomplete-metamorphosis","nymph","moulting","external-fertilization","internal-fertilization","zygote","embryo","yolk","petal","sepal","stamen","anther","filament","carpel","stigma","style","ovary","pollination","pollen","pollinator","nectar","self-pollination","cross-pollination","seed","fruit"]}]},{"id":"earth","title":"سطح الأرض المتغير","lessons":[{"id":"earth-structure","title":"بنية الأرض والزلازل والبراكين","start":104,"end":115,"terms":["atmosphere","hydrosphere","biosphere","crust","mantle","lithosphere","asthenosphere","core","outer-core","inner-core","tectonic-plate","fault","earthquake","seismic-waves","focus","epicenter","seismometer","magnitude","richter","tsunami","volcano","magma","lava","crater","active-volcano","dormant-volcano","extinct-volcano","lava-field"]},{"id":"weathering","title":"التجوية والتعرية والتربة","start":116,"end":131,"terms":["weathering","physical-weathering","chemical-weathering","acid-rain","erosion","glacier","deposition","sediment","delta","sandbar","barrier-island","dune","soil","organic-matter","soil-horizon","humus","topsoil","subsoil","parent-material","pollution","soil-conservation","fertilizing","crop-rotation","strip-cropping","contour-plowing","terrace","windbreak"]}]}],"terms":[{"id":"classification","name":"التصنيف","meaning":"وضع المخلوقات الحية في مجموعات حسب صفاتها المشتركة.","example":"نجمع القطط في مجموعة تختلف عن مجموعة النباتات.","page":14,"aliases":[],"unit":"classification","lesson":"levels","image":"images/classification.webp","audioText":"التصنيف. وضع المخلوقات الحية في مجموعات حسب صفاتها المشتركة. مثال. نجمع القطط في مجموعة تختلف عن مجموعة النباتات.","imageQuiz":false},{"id":"kingdom","name":"المملكة","meaning":"أوسع مستوى في التصنيف الذي يعرضه الدرس، وتضم مجموعات كثيرة.","example":"مملكة الحيوانات تضم الحصان والفراشة.","page":14,"aliases":[],"unit":"classification","lesson":"levels","image":"images/kingdom.webp","audioText":"المملكة. أوسع مستوى في التصنيف الذي يعرضه الدرس، وتضم مجموعات كثيرة. مثال. مملكة الحيوانات تضم الحصان والفراشة.","imageQuiz":false},{"id":"phylum","name":"الشعبة","meaning":"مستوى داخل المملكة يضم طوائف متشابهة.","example":"الحبليات شعبة تضم حيوانات لها صفات مشتركة.","page":15,"aliases":[],"unit":"classification","lesson":"levels","image":"images/phylum.webp","audioText":"الشعبة. مستوى داخل المملكة يضم طوائف متشابهة. مثال. الحبليات شعبة تضم حيوانات لها صفات مشتركة.","imageQuiz":false},{"id":"class","name":"الطائفة","meaning":"مجموعة داخل الشعبة تضم رتبًا متشابهة.","example":"الحصان من طائفة الثدييات.","page":15,"aliases":[],"unit":"classification","lesson":"levels","image":"images/class.webp","audioText":"الطائفة. مجموعة داخل الشعبة تضم رتبًا متشابهة. مثال. الحصان من طائفة الثدييات.","imageQuiz":false},{"id":"order","name":"الرتبة","meaning":"مجموعة داخل الطائفة تضم فصائل متشابهة.","example":"رتبة الفرديات تضم الحصان وأقرباءه.","page":15,"aliases":[],"unit":"classification","lesson":"levels","image":"images/order.webp","audioText":"الرتبة. مجموعة داخل الطائفة تضم فصائل متشابهة. مثال. رتبة الفرديات تضم الحصان وأقرباءه.","imageQuiz":false},{"id":"family","name":"الفصيلة","meaning":"مجموعة داخل الرتبة تضم أجناسًا متقاربة.","example":"ينتمي الحصان إلى الفصيلة الخيلية.","page":15,"aliases":[],"unit":"classification","lesson":"levels","image":"images/family.webp","audioText":"الفصيلة. مجموعة داخل الرتبة تضم أجناسًا متقاربة. مثال. ينتمي الحصان إلى الفصيلة الخيلية.","imageQuiz":false},{"id":"genus","name":"الجنس","meaning":"مجموعة من الأنواع المتقاربة في صفاتها.","example":"الحصان والحمار من جنس إيكوس.","page":15,"aliases":[],"unit":"classification","lesson":"levels","image":"images/genus.webp","audioText":"الجنس. مجموعة من الأنواع المتقاربة في صفاتها. مثال. الحصان والحمار من جنس إيكوس.","imageQuiz":false},{"id":"species","name":"النوع","meaning":"أصغر مستوى في التصنيف؛ أفراده متشابهة ويمكنها التكاثر لإنتاج أفراد قادرة على التكاثر.","example":"القطط المنزلية تنتمي إلى نوع واحد.","page":15,"aliases":[],"unit":"classification","lesson":"levels","image":"images/species.webp","audioText":"النوع. أصغر مستوى في التصنيف؛ أفراده متشابهة ويمكنها التكاثر لإنتاج أفراد قادرة على التكاثر. مثال. القطط المنزلية تنتمي إلى نوع واحد.","imageQuiz":false},{"id":"plants","name":"النباتات","meaning":"مخلوقات تصنع غذاءها باستخدام ضوء الشمس.","example":"نبات الفاصولياء يصنع غذاءه في أوراقه.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/plants.webp","audioText":"النباتات. مخلوقات تصنع غذاءها باستخدام ضوء الشمس. مثال. نبات الفاصولياء يصنع غذاءه في أوراقه.","imageQuiz":false},{"id":"animals","name":"الحيوانات","meaning":"مخلوقات تحصل على غذائها من مخلوقات أخرى.","example":"الحصان يأكل النباتات.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/animals.webp","audioText":"الحيوانات. مخلوقات تحصل على غذائها من مخلوقات أخرى. مثال. الحصان يأكل النباتات.","imageQuiz":false},{"id":"vertebrates","name":"الفقاريات","meaning":"حيوانات لها عمود فقري.","example":"الحصان من الفقاريات.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/vertebrates.webp","audioText":"الفقاريات. حيوانات لها عمود فقري. مثال. الحصان من الفقاريات.","imageQuiz":false},{"id":"invertebrates","name":"اللافقاريات","meaning":"حيوانات ليس لها عمود فقري.","example":"الفراشة ودودة الأرض من اللافقاريات.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/invertebrates.webp","audioText":"اللافقاريات. حيوانات ليس لها عمود فقري. مثال. الفراشة ودودة الأرض من اللافقاريات.","imageQuiz":false},{"id":"fungi","name":"الفطريات","meaning":"مخلوقات مثل عيش الغراب والعفن، لا تصنع غذاءها بنفسها وتمتص الغذاء من محيطها.","example":"عيش الغراب من الفطريات.","page":18,"aliases":[],"unit":"classification","lesson":"levels","image":"images/fungi.webp","audioText":"الفطريات. مخلوقات مثل عيش الغراب والعفن، لا تصنع غذاءها بنفسها وتمتص الغذاء من محيطها. مثال. عيش الغراب من الفطريات.","imageQuiz":true},{"id":"bacteria","name":"البكتيريا","meaning":"مخلوقات مجهرية وحيدة الخلية، لا تحتوي خلاياها على نواة حقيقية، ومنها النافع ومنها الضار.","example":"بعض البكتيريا تساعد أجسامنا على الهضم.","page":19,"aliases":[],"unit":"classification","lesson":"levels","image":"images/bacteria.webp","audioText":"البكتيريا. مخلوقات مجهرية وحيدة الخلية، لا تحتوي خلاياها على نواة حقيقية، ومنها النافع ومنها الضار. مثال. بعض البكتيريا تساعد أجسامنا على الهضم.","imageQuiz":true},{"id":"protists","name":"الطلائعيات","meaning":"مجموعة متنوعة من المخلوقات، لخلاياها نواة حقيقية، ومنها الأميبا والبراميسيوم وبعض الطحالب.","example":"الأميبا من الطلائعيات.","page":19,"aliases":[],"unit":"classification","lesson":"levels","image":"images/protists.webp","audioText":"الطلائعيات. مجموعة متنوعة من المخلوقات، لخلاياها نواة حقيقية، ومنها الأميبا والبراميسيوم وبعض الطحالب. مثال. الأميبا من الطلائعيات.","imageQuiz":false},{"id":"vascular","name":"النباتات الوعائية","meaning":"نباتات فيها أنسجة تنقل الماء والغذاء بين أجزائها.","example":"الفاصولياء نبات وعائي.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/vascular.webp","audioText":"النباتات الوعائية. نباتات فيها أنسجة تنقل الماء والغذاء بين أجزائها. مثال. الفاصولياء نبات وعائي.","imageQuiz":false},{"id":"nonvascular","name":"النباتات اللاوعائية","meaning":"نباتات ليس فيها أنسجة وعائية متخصصة لنقل الماء والغذاء.","example":"الحزازيات نباتات لاوعائية.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/nonvascular.webp","audioText":"النباتات اللاوعائية. نباتات ليس فيها أنسجة وعائية متخصصة لنقل الماء والغذاء. مثال. الحزازيات نباتات لاوعائية.","imageQuiz":false},{"id":"root","name":"الجذر","meaning":"جزء يثبت النبات ويمتص الماء والأملاح من التربة.","example":"يمتص جذر الجزر الماء من التربة.","page":24,"aliases":[],"unit":"classification","lesson":"plants","image":"images/root.webp","audioText":"الجذر. جزء يثبت النبات ويمتص الماء والأملاح من التربة. مثال. يمتص جذر الجزر الماء من التربة.","imageQuiz":true},{"id":"root-hairs","name":"الشعيرات الجذرية","meaning":"تراكيب دقيقة تزيد قدرة الجذر على امتصاص الماء والأملاح.","example":"تنتشر الشعيرات على أجزاء من الجذر.","page":24,"aliases":[],"unit":"classification","lesson":"plants","image":"images/root-hairs.webp","audioText":"الشعيرات الجذرية. تراكيب دقيقة تزيد قدرة الجذر على امتصاص الماء والأملاح. مثال. تنتشر الشعيرات على أجزاء من الجذر.","imageQuiz":true},{"id":"taproot","name":"الجذور الوتدية","meaning":"جذور لها جذر رئيس كبير تتفرع منه جذور أصغر.","example":"الجزر له جذر وتدي.","page":25,"aliases":[],"unit":"classification","lesson":"plants","image":"images/taproot.webp","audioText":"الجذور الوتدية. جذور لها جذر رئيس كبير تتفرع منه جذور أصغر. مثال. الجزر له جذر وتدي.","imageQuiz":true},{"id":"fibrous","name":"الجذور الليفية","meaning":"جذور رفيعة كثيرة متقاربة الحجم.","example":"للحشائش جذور ليفية.","page":25,"aliases":[],"unit":"classification","lesson":"plants","image":"images/fibrous.webp","audioText":"الجذور الليفية. جذور رفيعة كثيرة متقاربة الحجم. مثال. للحشائش جذور ليفية.","imageQuiz":true},{"id":"stem","name":"الساق","meaning":"جزء يدعم النبات ويحمل الأوراق، وتنقل أنسجته الماء والغذاء.","example":"ترفع الساق الأوراق نحو الضوء.","page":26,"aliases":[],"unit":"classification","lesson":"plants","image":"images/stem.webp","audioText":"الساق. جزء يدعم النبات ويحمل الأوراق، وتنقل أنسجته الماء والغذاء. مثال. ترفع الساق الأوراق نحو الضوء.","imageQuiz":true},{"id":"xylem","name":"الخشب","meaning":"نسيج وعائي ينقل الماء والأملاح من الجذور إلى بقية النبات.","example":"يصعد الماء إلى الأوراق عبر الخشب.","page":26,"aliases":[],"unit":"classification","lesson":"plants","image":"images/xylem.webp","audioText":"الخشب. نسيج وعائي ينقل الماء والأملاح من الجذور إلى بقية النبات. مثال. يصعد الماء إلى الأوراق عبر الخشب.","imageQuiz":true},{"id":"phloem","name":"اللحاء","meaning":"نسيج وعائي ينقل الغذاء الذي يصنعه النبات إلى أجزائه.","example":"ينقل اللحاء السكر إلى الجذور.","page":26,"aliases":[],"unit":"classification","lesson":"plants","image":"images/phloem.webp","audioText":"اللحاء. نسيج وعائي ينقل الغذاء الذي يصنعه النبات إلى أجزائه. مثال. ينقل اللحاء السكر إلى الجذور.","imageQuiz":true},{"id":"leaf","name":"الورقة","meaning":"جزء يصنع معظم غذاء النبات باستخدام الضوء.","example":"تستقبل الورقة ضوء الشمس.","page":28,"aliases":[],"unit":"classification","lesson":"plants","image":"images/leaf.webp","audioText":"الورقة. جزء يصنع معظم غذاء النبات باستخدام الضوء. مثال. تستقبل الورقة ضوء الشمس.","imageQuiz":true},{"id":"photosynthesis","name":"البناء الضوئي","meaning":"عملية يصنع فيها النبات السكر من الماء وثاني أكسيد الكربون باستخدام الضوء، وينتج عنها الأكسجين.","example":"تستخدم الورقة ضوء الشمس لصنع الغذاء.","page":28,"aliases":[],"unit":"classification","lesson":"plants","image":"images/photosynthesis.webp","audioText":"البناء الضوئي. عملية يصنع فيها النبات السكر من الماء وثاني أكسيد الكربون باستخدام الضوء، وينتج عنها الأكسجين. مثال. تستخدم الورقة ضوء الشمس لصنع الغذاء.","imageQuiz":true},{"id":"stomata","name":"الثغور","meaning":"فتحات صغيرة في الورقة تمر عبرها الغازات وبخار الماء.","example":"يدخل ثاني أكسيد الكربون عبر الثغور.","page":28,"aliases":[],"unit":"classification","lesson":"plants","image":"images/stomata.webp","audioText":"الثغور. فتحات صغيرة في الورقة تمر عبرها الغازات وبخار الماء. مثال. يدخل ثاني أكسيد الكربون عبر الثغور.","imageQuiz":true},{"id":"transpiration","name":"النتح","meaning":"خروج الماء من النبات على هيئة بخار، ويحدث معظمه عبر ثغور الأوراق.","example":"تفقد الورقة بعض الماء بعملية النتح.","page":28,"aliases":[],"unit":"classification","lesson":"plants","image":"images/transpiration.webp","audioText":"النتح. خروج الماء من النبات على هيئة بخار، ويحدث معظمه عبر ثغور الأوراق. مثال. تفقد الورقة بعض الماء بعملية النتح.","imageQuiz":true},{"id":"cell","name":"الخلية","meaning":"وحدة بناء المخلوق الحي، وتقوم بعمليات الحياة.","example":"تتكون البكتيريا من خلية واحدة.","page":14,"aliases":[],"unit":"classification","lesson":"levels","image":"images/cell.webp","audioText":"الخلية. وحدة بناء المخلوق الحي، وتقوم بعمليات الحياة. مثال. تتكون البكتيريا من خلية واحدة.","imageQuiz":false},{"id":"unicellular","name":"وحيد الخلية","meaning":"مخلوق حي يتكون جسمه من خلية واحدة.","example":"الأميبا مخلوق وحيد الخلية.","page":19,"aliases":["وحيدة الخلية"],"unit":"classification","lesson":"levels","image":"images/unicellular.webp","audioText":"وحيد الخلية. مخلوق حي يتكون جسمه من خلية واحدة. مثال. الأميبا مخلوق وحيد الخلية.","imageQuiz":false},{"id":"multicellular","name":"متعدد الخلايا","meaning":"مخلوق حي يتكون جسمه من خلايا كثيرة.","example":"الحصان مخلوق متعدد الخلايا.","page":16,"aliases":["متعددة الخلايا"],"unit":"classification","lesson":"levels","image":"images/multicellular.webp","audioText":"متعدد الخلايا. مخلوق حي يتكون جسمه من خلايا كثيرة. مثال. الحصان مخلوق متعدد الخلايا.","imageQuiz":false},{"id":"scientific-name","name":"الاسم العلمي","meaning":"اسم يحدد المخلوق الحي، ويتكون في أمثلة الدرس من اسم الجنس واسم النوع.","example":"يستعمل العلماء الاسم العلمي لتحديد الحصان.","page":14,"aliases":[],"unit":"classification","lesson":"levels","image":"images/scientific-name.webp","audioText":"الاسم العلمي. اسم يحدد المخلوق الحي، ويتكون في أمثلة الدرس من اسم الجنس واسم النوع. مثال. يستعمل العلماء الاسم العلمي لتحديد الحصان.","imageQuiz":true},{"id":"sponges","name":"الإسفنجيات","meaning":"حيوانات مائية لا فقارية، تحتوي أجسامها على ثقوب يمر خلالها الماء.","example":"الإسفنج من الحيوانات اللافقارية.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/sponges.webp","audioText":"الإسفنجيات. حيوانات مائية لا فقارية، تحتوي أجسامها على ثقوب يمر خلالها الماء. مثال. الإسفنج من الحيوانات اللافقارية.","imageQuiz":true},{"id":"cnidarians","name":"اللاسعات","meaning":"حيوانات لا فقارية تمتلك خلايا لاسعة تساعدها على الحصول على الغذاء.","example":"قنديل البحر من اللاسعات.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/cnidarians.webp","audioText":"اللاسعات. حيوانات لا فقارية تمتلك خلايا لاسعة تساعدها على الحصول على الغذاء. مثال. قنديل البحر من اللاسعات.","imageQuiz":true},{"id":"flatworms","name":"الديدان المفلطحة","meaning":"ديدان لا فقارية أجسامها مسطحة.","example":"الدودة الشريطية من الديدان المفلطحة.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/flatworms.webp","audioText":"الديدان المفلطحة. ديدان لا فقارية أجسامها مسطحة. مثال. الدودة الشريطية من الديدان المفلطحة.","imageQuiz":true},{"id":"roundworms","name":"الديدان الأسطوانية","meaning":"ديدان لا فقارية أجسامها أسطوانية غير مقسمة إلى حلقات.","example":"دودة الإسكارس من الديدان الأسطوانية.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/roundworms.webp","audioText":"الديدان الأسطوانية. ديدان لا فقارية أجسامها أسطوانية غير مقسمة إلى حلقات. مثال. دودة الإسكارس من الديدان الأسطوانية.","imageQuiz":true},{"id":"annelids","name":"الديدان الحلقية","meaning":"ديدان لا فقارية أجسامها مقسمة إلى حلقات.","example":"دودة الأرض من الديدان الحلقية.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/annelids.webp","audioText":"الديدان الحلقية. ديدان لا فقارية أجسامها مقسمة إلى حلقات. مثال. دودة الأرض من الديدان الحلقية.","imageQuiz":true},{"id":"molluscs","name":"الرخويات","meaning":"حيوانات لا فقارية رخوة الجسم، لبعضها أصداف.","example":"الحلزون من الرخويات.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/molluscs.webp","audioText":"الرخويات. حيوانات لا فقارية رخوة الجسم، لبعضها أصداف. مثال. الحلزون من الرخويات.","imageQuiz":true},{"id":"arthropods","name":"المفصليات","meaning":"حيوانات لا فقارية لها أرجل مفصلية وهيكل خارجي.","example":"اليعسوب من المفصليات.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/arthropods.webp","audioText":"المفصليات. حيوانات لا فقارية لها أرجل مفصلية وهيكل خارجي. مثال. اليعسوب من المفصليات.","imageQuiz":false},{"id":"echinoderms","name":"شوكيات الجلد","meaning":"حيوانات بحرية لا فقارية، لها تراكيب شوكية في الجلد أو تحته.","example":"نجم البحر من شوكيات الجلد.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/echinoderms.webp","audioText":"شوكيات الجلد. حيوانات بحرية لا فقارية، لها تراكيب شوكية في الجلد أو تحته. مثال. نجم البحر من شوكيات الجلد.","imageQuiz":true},{"id":"fish","name":"الأسماك","meaning":"فقاريات مائية تتنفس بالخياشيم ولها زعانف.","example":"تستخدم السمكة زعانفها في الحركة.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/fish.webp","audioText":"الأسماك. فقاريات مائية تتنفس بالخياشيم ولها زعانف. مثال. تستخدم السمكة زعانفها في الحركة.","imageQuiz":false},{"id":"amphibians","name":"البرمائيات","meaning":"فقاريات لها جلد رطب، ويعيش كثير منها في الماء في بداية حياته، ويتنفس البالغ منها بالرئتين والجلد.","example":"الضفدع من البرمائيات.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/amphibians.webp","audioText":"البرمائيات. فقاريات لها جلد رطب، ويعيش كثير منها في الماء في بداية حياته، ويتنفس البالغ منها بالرئتين والجلد. مثال. الضفدع من البرمائيات.","imageQuiz":true},{"id":"reptiles","name":"الزواحف","meaning":"فقاريات يغطي جسمها جلد جاف ذو حراشف.","example":"التمساح من الزواحف.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/reptiles.webp","audioText":"الزواحف. فقاريات يغطي جسمها جلد جاف ذو حراشف. مثال. التمساح من الزواحف.","imageQuiz":true},{"id":"birds","name":"الطيور","meaning":"فقاريات يغطي جسمها الريش ولها مناقير.","example":"الصقر من الطيور.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/birds.webp","audioText":"الطيور. فقاريات يغطي جسمها الريش ولها مناقير. مثال. الصقر من الطيور.","imageQuiz":true},{"id":"mammals","name":"الثدييات","meaning":"فقاريات لها شعر أو فرو، وترضع صغارها الحليب.","example":"البقرة من الثدييات.","page":16,"aliases":[],"unit":"classification","lesson":"levels","image":"images/mammals.webp","audioText":"الثدييات. فقاريات لها شعر أو فرو، وترضع صغارها الحليب. مثال. البقرة من الثدييات.","imageQuiz":true},{"id":"seed-plants","name":"النباتات البذرية","meaning":"نباتات تنتج بذورًا يمكن أن تنمو إلى نباتات جديدة.","example":"الصنوبر والقرع نباتات بذرية.","page":17,"aliases":[],"unit":"classification","lesson":"levels","image":"images/seed-plants.webp","audioText":"النباتات البذرية. نباتات تنتج بذورًا يمكن أن تنمو إلى نباتات جديدة. مثال. الصنوبر والقرع نباتات بذرية.","imageQuiz":false},{"id":"seedless","name":"النباتات اللابذرية","meaning":"نباتات لا تنتج بذورًا، ويتكاثر كثير منها بالأبواغ.","example":"السرخس مثال لنبات لابذري.","page":17,"aliases":[],"unit":"classification","lesson":"levels","image":"images/seedless.webp","audioText":"النباتات اللابذرية. نباتات لا تنتج بذورًا، ويتكاثر كثير منها بالأبواغ. مثال. السرخس مثال لنبات لابذري.","imageQuiz":false},{"id":"gymnosperms","name":"النباتات معرّاة البذور","meaning":"نباتات بذرية لا تنتج أزهارًا، ولا تحيط ثمار ببذورها.","example":"يحمل الصنوبر بذوره في مخاريط.","page":17,"aliases":["معراة البذور","النباتات المعراة البذور"],"unit":"classification","lesson":"levels","image":"images/gymnosperms.webp","audioText":"النباتات معرّاة البذور. نباتات بذرية لا تنتج أزهارًا، ولا تحيط ثمار ببذورها. مثال. يحمل الصنوبر بذوره في مخاريط.","imageQuiz":false},{"id":"angiosperms","name":"النباتات مغطّاة البذور","meaning":"نباتات بذرية تنتج أزهارًا، وتكون بذورها داخل ثمار.","example":"توجد بذور القرع داخل ثمرته.","page":17,"aliases":["مغطاة البذور","النباتات المغطاة البذور"],"unit":"classification","lesson":"levels","image":"images/angiosperms.webp","audioText":"النباتات مغطّاة البذور. نباتات بذرية تنتج أزهارًا، وتكون بذورها داخل ثمار. مثال. توجد بذور القرع داخل ثمرته.","imageQuiz":false},{"id":"archaea","name":"البكتيريا البدائية","meaning":"مخلوقات مجهرية وحيدة الخلية، يعيش بعضها في ظروف قاسية.","example":"يعيش بعض أفرادها في المياه الحارة.","page":19,"aliases":[],"unit":"classification","lesson":"levels","image":"images/archaea.webp","audioText":"البكتيريا البدائية. مخلوقات مجهرية وحيدة الخلية، يعيش بعضها في ظروف قاسية. مثال. يعيش بعض أفرادها في المياه الحارة.","imageQuiz":false},{"id":"true-bacteria","name":"البكتيريا الحقيقية","meaning":"مخلوقات مجهرية وحيدة الخلية، تنتشر في بيئات كثيرة، ومنها النافع والضار.","example":"تساعد بعض البكتيريا على الهضم.","page":19,"aliases":[],"unit":"classification","lesson":"levels","image":"images/true-bacteria.webp","audioText":"البكتيريا الحقيقية. مخلوقات مجهرية وحيدة الخلية، تنتشر في بيئات كثيرة، ومنها النافع والضار. مثال. تساعد بعض البكتيريا على الهضم.","imageQuiz":false},{"id":"virus","name":"الفيروسات","meaning":"تراكيب دقيقة لا تتكاثر وحدها، بل تحتاج إلى خلايا مخلوق حي.","example":"تسبب بعض الفيروسات الإنفلونزا.","page":20,"aliases":["الفيروس"],"unit":"classification","lesson":"levels","image":"images/virus.webp","audioText":"الفيروسات. تراكيب دقيقة لا تتكاثر وحدها، بل تحتاج إلى خلايا مخلوق حي. مثال. تسبب بعض الفيروسات الإنفلونزا.","imageQuiz":true},{"id":"root-cap","name":"القلنسوة","meaning":"غطاء يحمي قمة الجذر في أثناء اختراق التربة.","example":"تحمي القلنسوة الأنسجة عند طرف الجذر.","page":24,"aliases":[],"unit":"classification","lesson":"plants","image":"images/root-cap.webp","audioText":"القلنسوة. غطاء يحمي قمة الجذر في أثناء اختراق التربة. مثال. تحمي القلنسوة الأنسجة عند طرف الجذر.","imageQuiz":true},{"id":"epidermis","name":"البشرة","meaning":"طبقة خارجية تغطي أجزاء النبات وتحميها.","example":"تخرج الشعيرات الجذرية من بشرة الجذر.","page":24,"aliases":[],"unit":"classification","lesson":"plants","image":"images/epidermis.webp","audioText":"البشرة. طبقة خارجية تغطي أجزاء النبات وتحميها. مثال. تخرج الشعيرات الجذرية من بشرة الجذر.","imageQuiz":true},{"id":"cortex","name":"القشرة","meaning":"طبقة داخل الجذر تقع بعد البشرة وتختزن الغذاء.","example":"يوجد غذاء مخزون في قشرة الجذر.","page":24,"aliases":[],"unit":"classification","lesson":"plants","image":"images/cortex.webp","audioText":"القشرة. طبقة داخل الجذر تقع بعد البشرة وتختزن الغذاء. مثال. يوجد غذاء مخزون في قشرة الجذر.","imageQuiz":true},{"id":"vascular-tissue","name":"النسيج الوعائي","meaning":"أنسجة متخصصة تنقل الماء والأملاح والغذاء داخل النبات.","example":"الخشب واللحاء نسيجان وعائيان.","page":24,"aliases":["أوعية النقل","الجهاز الوعائي"],"unit":"classification","lesson":"plants","image":"images/vascular-tissue.webp","audioText":"النسيج الوعائي. أنسجة متخصصة تنقل الماء والأملاح والغذاء داخل النبات. مثال. الخشب واللحاء نسيجان وعائيان.","imageQuiz":true},{"id":"spreading-roots","name":"الجذور المستعرضة","meaning":"مجموعة من الجذور يذكر الدرس ضمنها الجذور الهوائية والجذور الدعامية.","example":"منها جذور تمتد فوق سطح التربة أو تدعم الساق.","page":25,"aliases":[],"unit":"classification","lesson":"plants","image":"images/spreading-roots.webp","audioText":"الجذور المستعرضة. مجموعة من الجذور يذكر الدرس ضمنها الجذور الهوائية والجذور الدعامية. مثال. منها جذور تمتد فوق سطح التربة أو تدعم الساق.","imageQuiz":true},{"id":"aerial-roots","name":"الجذور الهوائية","meaning":"جذور تنمو فوق سطح الأرض ويمكن أن تمتص الرطوبة من الهواء.","example":"لبعض نباتات الأوركيد جذور هوائية.","page":25,"aliases":[],"unit":"classification","lesson":"plants","image":"images/aerial-roots.webp","audioText":"الجذور الهوائية. جذور تنمو فوق سطح الأرض ويمكن أن تمتص الرطوبة من الهواء. مثال. لبعض نباتات الأوركيد جذور هوائية.","imageQuiz":true},{"id":"prop-roots","name":"الجذور الدعامية","meaning":"جذور تساعد على دعم النبات وتثبيته.","example":"تساعد الجذور الدعامية بعض النباتات في التربة الرخوة.","page":25,"aliases":[],"unit":"classification","lesson":"plants","image":"images/prop-roots.webp","audioText":"الجذور الدعامية. جذور تساعد على دعم النبات وتثبيته. مثال. تساعد الجذور الدعامية بعض النباتات في التربة الرخوة.","imageQuiz":true},{"id":"soft-stem","name":"الساق اللينة","meaning":"ساق خضراء طرية يمكن ثنيها بسهولة نسبيًا.","example":"لنبات النعناع ساق لينة.","page":26,"aliases":[],"unit":"classification","lesson":"plants","image":"images/soft-stem.webp","audioText":"الساق اللينة. ساق خضراء طرية يمكن ثنيها بسهولة نسبيًا. مثال. لنبات النعناع ساق لينة.","imageQuiz":true},{"id":"woody-stem","name":"الساق الخشبية","meaning":"ساق صلبة قوية تدعم الشجيرات والأشجار.","example":"لشجرة التفاح ساق خشبية.","page":26,"aliases":[],"unit":"classification","lesson":"plants","image":"images/woody-stem.webp","audioText":"الساق الخشبية. ساق صلبة قوية تدعم الشجيرات والأشجار. مثال. لشجرة التفاح ساق خشبية.","imageQuiz":true},{"id":"cambium","name":"الكامبيوم","meaning":"طبقة تنتج خلايا جديدة من الخشب واللحاء وتقع بينهما.","example":"يسهم الكامبيوم في زيادة سمك الساق.","page":27,"aliases":[],"unit":"classification","lesson":"plants","image":"images/cambium.webp","audioText":"الكامبيوم. طبقة تنتج خلايا جديدة من الخشب واللحاء وتقع بينهما. مثال. يسهم الكامبيوم في زيادة سمك الساق.","imageQuiz":true},{"id":"annual-rings","name":"الحلقات السنوية","meaning":"حلقات نمو تظهر في مقطع جذع الشجرة، وتساعد على تقدير عمرها.","example":"يمكن عد الحلقات لتقدير عمر شجرة.","page":27,"aliases":[],"unit":"classification","lesson":"plants","image":"images/annual-rings.webp","audioText":"الحلقات السنوية. حلقات نمو تظهر في مقطع جذع الشجرة، وتساعد على تقدير عمرها. مثال. يمكن عد الحلقات لتقدير عمر شجرة.","imageQuiz":true},{"id":"chlorophyll","name":"الكلوروفيل","meaning":"صبغة خضراء تمتص طاقة الضوء اللازمة للبناء الضوئي.","example":"يعطي الكلوروفيل الأوراق لونها الأخضر.","page":28,"aliases":[],"unit":"classification","lesson":"plants","image":"images/chlorophyll.webp","audioText":"الكلوروفيل. صبغة خضراء تمتص طاقة الضوء اللازمة للبناء الضوئي. مثال. يعطي الكلوروفيل الأوراق لونها الأخضر.","imageQuiz":true},{"id":"chloroplast","name":"البلاستيدات الخضراء","meaning":"تراكيب في الخلايا النباتية تحتوي الكلوروفيل ويحدث فيها البناء الضوئي.","example":"تصنع الخلية السكر داخل البلاستيدات الخضراء.","page":29,"aliases":[],"unit":"classification","lesson":"plants","image":"images/chloroplast.webp","audioText":"البلاستيدات الخضراء. تراكيب في الخلايا النباتية تحتوي الكلوروفيل ويحدث فيها البناء الضوئي. مثال. تصنع الخلية السكر داخل البلاستيدات الخضراء.","imageQuiz":true},{"id":"guard-cells","name":"الخلايا الحارسة","meaning":"خلايا تحيط بالثغر وتتحكم في فتحه وإغلاقه.","example":"يتغير شكل الخليتين الحارستين عند فتح الثغر.","page":28,"aliases":[],"unit":"classification","lesson":"plants","image":"images/guard-cells.webp","audioText":"الخلايا الحارسة. خلايا تحيط بالثغر وتتحكم في فتحه وإغلاقه. مثال. يتغير شكل الخليتين الحارستين عند فتح الثغر.","imageQuiz":false},{"id":"leaf-vein","name":"عِرق الورقة","meaning":"تركيب داخل الورقة يضم أنسجة نقل الماء والغذاء.","example":"تتفرع العروق في نصل الورقة.","page":28,"aliases":["عروق الورقة","العرق"],"unit":"classification","lesson":"plants","image":"images/leaf-vein.webp","audioText":"عِرق الورقة. تركيب داخل الورقة يضم أنسجة نقل الماء والغذاء. مثال. تتفرع العروق في نصل الورقة.","imageQuiz":true},{"id":"waxy-layer","name":"الطبقة الشمعية","meaning":"غطاء يقلل فقد الماء من سطح الورقة.","example":"تساعد الطبقة الشمعية على تقليل تبخر الماء.","page":28,"aliases":[],"unit":"classification","lesson":"plants","image":"images/waxy-layer.webp","audioText":"الطبقة الشمعية. غطاء يقلل فقد الماء من سطح الورقة. مثال. تساعد الطبقة الشمعية على تقليل تبخر الماء.","imageQuiz":true},{"id":"starch","name":"النشا","meaning":"مادة يخزن النبات فيها بعض السكر الزائد ليستفيد منها لاحقًا.","example":"يخزن نبات البطاطس النشا في درناته.","page":29,"aliases":[],"unit":"classification","lesson":"plants","image":"images/starch.webp","audioText":"النشا. مادة يخزن النبات فيها بعض السكر الزائد ليستفيد منها لاحقًا. مثال. يخزن نبات البطاطس النشا في درناته.","imageQuiz":true},{"id":"matter","name":"المادة","meaning":"كل ما له كتلة ويشغل حيزًا.","example":"الماء والهواء مواد.","page":38,"aliases":[],"unit":"matter","lesson":"elements","image":"images/matter.webp","audioText":"المادة. كل ما له كتلة ويشغل حيزًا. مثال. الماء والهواء مواد.","imageQuiz":false},{"id":"element","name":"العنصر","meaning":"مادة نقية لا تتجزأ إلى مواد أبسط بالتفاعلات الكيميائية.","example":"الحديد عنصر.","page":38,"aliases":[],"unit":"matter","lesson":"elements","image":"images/element.webp","audioText":"العنصر. مادة نقية لا تتجزأ إلى مواد أبسط بالتفاعلات الكيميائية. مثال. الحديد عنصر.","imageQuiz":true},{"id":"atom","name":"الذرّة","meaning":"أصغر جزء من العنصر يحتفظ بصفاته الكيميائية.","example":"قطعة الألومنيوم مكونة من ذرات.","page":39,"aliases":["الذرة"],"unit":"matter","lesson":"elements","image":"images/atom.webp","audioText":"الذرّة. أصغر جزء من العنصر يحتفظ بصفاته الكيميائية. مثال. قطعة الألومنيوم مكونة من ذرات.","imageQuiz":true},{"id":"atomic-nucleus","name":"النواة","meaning":"مركز الذرة ويحتوي البروتونات والنيوترونات.","example":"تتركز النواة في وسط نموذج الذرة.","page":40,"aliases":["نواة الذرة"],"unit":"matter","lesson":"elements","image":"images/atomic-nucleus.webp","audioText":"النواة. مركز الذرة ويحتوي البروتونات والنيوترونات. مثال. تتركز النواة في وسط نموذج الذرة.","imageQuiz":true},{"id":"proton","name":"البروتون","meaning":"جسيم موجب الشحنة يوجد في نواة الذرة.","example":"تحتوي نواة ذرة الأكسجين على ثمانية بروتونات.","page":40,"aliases":[],"unit":"matter","lesson":"elements","image":"images/proton.webp","audioText":"البروتون. جسيم موجب الشحنة يوجد في نواة الذرة. مثال. تحتوي نواة ذرة الأكسجين على ثمانية بروتونات.","imageQuiz":true},{"id":"neutron","name":"النيوترون","meaning":"جسيم متعادل الشحنة يوجد في نواة الذرة.","example":"النيوترون لا يحمل شحنة كهربائية.","page":40,"aliases":[],"unit":"matter","lesson":"elements","image":"images/neutron.webp","audioText":"النيوترون. جسيم متعادل الشحنة يوجد في نواة الذرة. مثال. النيوترون لا يحمل شحنة كهربائية.","imageQuiz":true},{"id":"electron","name":"الإلكترون","meaning":"جسيم سالب الشحنة يوجد في المنطقة المحيطة بنواة الذرة.","example":"الإلكترونات خارج النواة.","page":40,"aliases":[],"unit":"matter","lesson":"elements","image":"images/electron.webp","audioText":"الإلكترون. جسيم سالب الشحنة يوجد في المنطقة المحيطة بنواة الذرة. مثال. الإلكترونات خارج النواة.","imageQuiz":true},{"id":"atomic-number","name":"العدد الذري","meaning":"عدد البروتونات في نواة ذرة العنصر.","example":"العدد الذري للأكسجين ثمانية.","page":40,"aliases":[],"unit":"matter","lesson":"elements","image":"images/atomic-number.webp","audioText":"العدد الذري. عدد البروتونات في نواة ذرة العنصر. مثال. العدد الذري للأكسجين ثمانية.","imageQuiz":true},{"id":"molecule","name":"الجزيء","meaning":"جسيم يتكون من ارتباط ذرتين أو أكثر.","example":"جزيء الأكسجين يتكون من ذرتي أكسجين.","page":41,"aliases":[],"unit":"matter","lesson":"elements","image":"images/molecule.webp","audioText":"الجزيء. جسيم يتكون من ارتباط ذرتين أو أكثر. مثال. جزيء الأكسجين يتكون من ذرتي أكسجين.","imageQuiz":true},{"id":"chemical-formula","name":"الصيغة الكيميائية","meaning":"رموز وأرقام تبين العناصر وعدد ذراتها في الجزيء أو المركب.","example":"تكتب صيغة الماء H₂O.","page":41,"aliases":[],"unit":"matter","lesson":"elements","image":"images/chemical-formula.webp","audioText":"الصيغة الكيميائية. رموز وأرقام تبين العناصر وعدد ذراتها في الجزيء أو المركب. مثال. تكتب صيغة الماء H₂O.","imageQuiz":true},{"id":"element-symbol","name":"رمز العنصر","meaning":"حرف أو حرفان يستخدمان للدلالة على العنصر.","example":"رمز الأكسجين O.","page":42,"aliases":["الرمز الكيميائي"],"unit":"matter","lesson":"elements","image":"images/element-symbol.webp","audioText":"رمز العنصر. حرف أو حرفان يستخدمان للدلالة على العنصر. مثال. رمز الأكسجين O.","imageQuiz":true},{"id":"periodic-table","name":"الجدول الدوري","meaning":"جدول تنظم فيه العناصر وفق أعدادها الذرية وخصائصها.","example":"نبحث عن رمز العنصر في الجدول الدوري.","page":42,"aliases":[],"unit":"matter","lesson":"elements","image":"images/periodic-table.webp","audioText":"الجدول الدوري. جدول تنظم فيه العناصر وفق أعدادها الذرية وخصائصها. مثال. نبحث عن رمز العنصر في الجدول الدوري.","imageQuiz":true},{"id":"period","name":"الدورة","meaning":"صف أفقي من العناصر في الجدول الدوري.","example":"يزداد العدد الذري عند الانتقال عبر الدورة.","page":42,"aliases":["الدورات"],"unit":"matter","lesson":"elements","image":"images/period.webp","audioText":"الدورة. صف أفقي من العناصر في الجدول الدوري. مثال. يزداد العدد الذري عند الانتقال عبر الدورة.","imageQuiz":true},{"id":"group","name":"المجموعة","meaning":"عمود رأسي في الجدول الدوري، تتشابه عناصره في خصائص كيميائية.","example":"تقع العناصر المتشابهة في عمود واحد.","page":43,"aliases":["المجموعات"],"unit":"matter","lesson":"elements","image":"images/group.webp","audioText":"المجموعة. عمود رأسي في الجدول الدوري، تتشابه عناصره في خصائص كيميائية. مثال. تقع العناصر المتشابهة في عمود واحد.","imageQuiz":true},{"id":"metal","name":"الفلزات","meaning":"عناصر تتميز غالبًا باللمعان وتوصيل الحرارة والكهرباء وقابلية التشكيل.","example":"النحاس من الفلزات.","page":48,"aliases":["الفلز"],"unit":"matter","lesson":"metals","image":"images/metal.webp","audioText":"الفلزات. عناصر تتميز غالبًا باللمعان وتوصيل الحرارة والكهرباء وقابلية التشكيل. مثال. النحاس من الفلزات.","imageQuiz":true},{"id":"nonmetal","name":"اللافلزات","meaning":"عناصر تختلف عن الفلزات، ومعظمها ضعيف التوصيل للحرارة والكهرباء.","example":"الكبريت من اللافلزات.","page":50,"aliases":["اللافلز"],"unit":"matter","lesson":"metals","image":"images/nonmetal.webp","audioText":"اللافلزات. عناصر تختلف عن الفلزات، ومعظمها ضعيف التوصيل للحرارة والكهرباء. مثال. الكبريت من اللافلزات.","imageQuiz":true},{"id":"metalloid","name":"أشباه الفلزات","meaning":"عناصر لها بعض خصائص الفلزات وبعض خصائص اللافلزات.","example":"السيليكون من أشباه الفلزات.","page":50,"aliases":["شبه الفلز"],"unit":"matter","lesson":"metals","image":"images/metalloid.webp","audioText":"أشباه الفلزات. عناصر لها بعض خصائص الفلزات وبعض خصائص اللافلزات. مثال. السيليكون من أشباه الفلزات.","imageQuiz":true},{"id":"malleability","name":"القابلية للطرق","meaning":"قابلية الفلز للتحول إلى صفائح بالطرق عليه دون أن ينكسر.","example":"يمكن طرق الذهب إلى صفائح رقيقة.","page":48,"aliases":[],"unit":"matter","lesson":"metals","image":"images/malleability.webp","audioText":"القابلية للطرق. قابلية الفلز للتحول إلى صفائح بالطرق عليه دون أن ينكسر. مثال. يمكن طرق الذهب إلى صفائح رقيقة.","imageQuiz":true},{"id":"ductility","name":"القابلية للسحب","meaning":"قابلية المادة للتشكيل في صورة أسلاك دون أن تتكسر.","example":"يسحب النحاس لصنع أسلاك.","page":48,"aliases":[],"unit":"matter","lesson":"metals","image":"images/ductility.webp","audioText":"القابلية للسحب. قابلية المادة للتشكيل في صورة أسلاك دون أن تتكسر. مثال. يسحب النحاس لصنع أسلاك.","imageQuiz":true},{"id":"corrosion","name":"التآكل","meaning":"تهالك الفلز نتيجة تفاعلات كيميائية مع مواد في البيئة.","example":"يؤدي تفاعل الحديد مع الأكسجين والرطوبة إلى صدئه.","page":48,"aliases":[],"unit":"matter","lesson":"metals","image":"images/corrosion.webp","audioText":"التآكل. تهالك الفلز نتيجة تفاعلات كيميائية مع مواد في البيئة. مثال. يؤدي تفاعل الحديد مع الأكسجين والرطوبة إلى صدئه.","imageQuiz":false},{"id":"conductor","name":"الموصل","meaning":"مادة تسمح بانتقال التيار الكهربائي أو الحرارة خلالها بكفاءة.","example":"يمر التيار في سلك النحاس.","page":48,"aliases":["مادة موصلة"],"unit":"matter","lesson":"metals","image":"images/conductor.webp","audioText":"الموصل. مادة تسمح بانتقال التيار الكهربائي أو الحرارة خلالها بكفاءة. مثال. يمر التيار في سلك النحاس.","imageQuiz":true},{"id":"semiconductor","name":"شبه الموصل","meaning":"مادة توصل التيار الكهربائي بكفاءة أقل من الفلزات ويمكن التحكم في توصيلها.","example":"يستخدم السيليكون في شرائح الحاسوب.","page":50,"aliases":[],"unit":"matter","lesson":"metals","image":"images/semiconductor.webp","audioText":"شبه الموصل. مادة توصل التيار الكهربائي بكفاءة أقل من الفلزات ويمكن التحكم في توصيلها. مثال. يستخدم السيليكون في شرائح الحاسوب.","imageQuiz":true},{"id":"insulator","name":"العازل","meaning":"مادة تعيق مرور التيار الكهربائي أو انتقال الحرارة.","example":"يغطي البلاستيك أسلاك الكهرباء لحمايتنا.","page":51,"aliases":["مادة عازلة"],"unit":"matter","lesson":"metals","image":"images/insulator.webp","audioText":"العازل. مادة تعيق مرور التيار الكهربائي أو انتقال الحرارة. مثال. يغطي البلاستيك أسلاك الكهرباء لحمايتنا.","imageQuiz":true},{"id":"noble-gases","name":"الغازات النبيلة","meaning":"مجموعة من العناصر الغازية قليلة التفاعل الكيميائي.","example":"الهيليوم والنيون من الغازات النبيلة.","page":50,"aliases":[],"unit":"matter","lesson":"metals","image":"images/noble-gases.webp","audioText":"الغازات النبيلة. مجموعة من العناصر الغازية قليلة التفاعل الكيميائي. مثال. الهيليوم والنيون من الغازات النبيلة.","imageQuiz":true},{"id":"physical-change","name":"التغير الفيزيائي","meaning":"تغير في الشكل أو الحجم أو الحالة دون تكون مادة جديدة.","example":"تمزيق الورق تغير فيزيائي.","page":60,"aliases":[],"unit":"changes","lesson":"states","image":"images/physical-change.webp","audioText":"التغير الفيزيائي. تغير في الشكل أو الحجم أو الحالة دون تكون مادة جديدة. مثال. تمزيق الورق تغير فيزيائي.","imageQuiz":false},{"id":"solid","name":"الحالة الصلبة","meaning":"حالة تحتفظ فيها المادة بشكل وحجم محددين في الظروف المعتادة.","example":"الجليد مادة صلبة.","page":60,"aliases":[],"unit":"changes","lesson":"states","image":"images/solid.webp","audioText":"الحالة الصلبة. حالة تحتفظ فيها المادة بشكل وحجم محددين في الظروف المعتادة. مثال. الجليد مادة صلبة.","imageQuiz":true},{"id":"liquid","name":"الحالة السائلة","meaning":"حالة لها حجم محدد وتأخذ شكل الوعاء.","example":"الماء السائل يأخذ شكل الكأس.","page":60,"aliases":[],"unit":"changes","lesson":"states","image":"images/liquid.webp","audioText":"الحالة السائلة. حالة لها حجم محدد وتأخذ شكل الوعاء. مثال. الماء السائل يأخذ شكل الكأس.","imageQuiz":true},{"id":"gas","name":"الحالة الغازية","meaning":"حالة تنتشر فيها المادة لتملأ الحيز المتاح.","example":"ينتشر بخار الماء في الهواء.","page":60,"aliases":[],"unit":"changes","lesson":"states","image":"images/gas.webp","audioText":"الحالة الغازية. حالة تنتشر فيها المادة لتملأ الحيز المتاح. مثال. ينتشر بخار الماء في الهواء.","imageQuiz":true},{"id":"melting","name":"الانصهار","meaning":"تحول المادة من الحالة الصلبة إلى السائلة باكتساب الحرارة.","example":"ينصهر الجليد عند تسخينه.","page":60,"aliases":[],"unit":"changes","lesson":"states","image":"images/melting.webp","audioText":"الانصهار. تحول المادة من الحالة الصلبة إلى السائلة باكتساب الحرارة. مثال. ينصهر الجليد عند تسخينه.","imageQuiz":true},{"id":"evaporation","name":"التبخر","meaning":"تحول المادة السائلة إلى غاز من سطحها.","example":"يجف الماء المتروك في صحن.","page":61,"aliases":[],"unit":"changes","lesson":"states","image":"images/evaporation.webp","audioText":"التبخر. تحول المادة السائلة إلى غاز من سطحها. مثال. يجف الماء المتروك في صحن.","imageQuiz":true},{"id":"condensation","name":"التكاثف","meaning":"تحول الغاز إلى سائل عند فقد الحرارة.","example":"تتكون قطرات ماء على كأس بارد.","page":61,"aliases":[],"unit":"changes","lesson":"states","image":"images/condensation.webp","audioText":"التكاثف. تحول الغاز إلى سائل عند فقد الحرارة. مثال. تتكون قطرات ماء على كأس بارد.","imageQuiz":true},{"id":"freezing","name":"التجمد","meaning":"تحول المادة من السائل إلى الصلب بفقد الحرارة.","example":"يتجمد الماء في المجمدة.","page":63,"aliases":[],"unit":"changes","lesson":"states","image":"images/freezing.webp","audioText":"التجمد. تحول المادة من السائل إلى الصلب بفقد الحرارة. مثال. يتجمد الماء في المجمدة.","imageQuiz":true},{"id":"sublimation","name":"التسامي","meaning":"تحول المادة من الصلب إلى الغاز مباشرة دون المرور بالسائل.","example":"يتسامى الجليد الجاف.","page":61,"aliases":[],"unit":"changes","lesson":"states","image":"images/sublimation.webp","audioText":"التسامي. تحول المادة من الصلب إلى الغاز مباشرة دون المرور بالسائل. مثال. يتسامى الجليد الجاف.","imageQuiz":true},{"id":"melting-point","name":"درجة الانصهار","meaning":"درجة الحرارة التي تبدأ عندها المادة الصلبة بالتحول إلى سائل.","example":"درجة انصهار الجليد النقي صفر مئوي عند الضغط المعتاد.","page":62,"aliases":[],"unit":"changes","lesson":"states","image":"images/melting-point.webp","audioText":"درجة الانصهار. درجة الحرارة التي تبدأ عندها المادة الصلبة بالتحول إلى سائل. مثال. درجة انصهار الجليد النقي صفر مئوي عند الضغط المعتاد.","imageQuiz":true},{"id":"boiling-point","name":"درجة الغليان","meaning":"درجة الحرارة التي يغلي عندها السائل عند ضغط معين.","example":"يغلي الماء النقي قرب مئة مئوية عند الضغط الجوي المعتاد.","page":62,"aliases":[],"unit":"changes","lesson":"states","image":"images/boiling-point.webp","audioText":"درجة الغليان. درجة الحرارة التي يغلي عندها السائل عند ضغط معين. مثال. يغلي الماء النقي قرب مئة مئوية عند الضغط الجوي المعتاد.","imageQuiz":true},{"id":"freezing-point","name":"درجة التجمد","meaning":"درجة الحرارة التي يبدأ عندها السائل بالتحول إلى صلب.","example":"يبدأ الماء النقي بالتجمد قرب صفر مئوي.","page":63,"aliases":[],"unit":"changes","lesson":"states","image":"images/freezing-point.webp","audioText":"درجة التجمد. درجة الحرارة التي يبدأ عندها السائل بالتحول إلى صلب. مثال. يبدأ الماء النقي بالتجمد قرب صفر مئوي.","imageQuiz":true},{"id":"thermal-expansion","name":"التمدد الحراري","meaning":"زيادة حجم المادة غالبًا عند ارتفاع درجة حرارتها.","example":"يزداد حجم الهواء في البالون عند تدفئته.","page":64,"aliases":[],"unit":"changes","lesson":"states","image":"images/thermal-expansion.webp","audioText":"التمدد الحراري. زيادة حجم المادة غالبًا عند ارتفاع درجة حرارتها. مثال. يزداد حجم الهواء في البالون عند تدفئته.","imageQuiz":true},{"id":"thermal-contraction","name":"الانكماش الحراري","meaning":"نقصان حجم المادة غالبًا عند انخفاض درجة حرارتها.","example":"ينكمش الهواء في البالون عند تبريده.","page":64,"aliases":[],"unit":"changes","lesson":"states","image":"images/thermal-contraction.webp","audioText":"الانكماش الحراري. نقصان حجم المادة غالبًا عند انخفاض درجة حرارتها. مثال. ينكمش الهواء في البالون عند تبريده.","imageQuiz":true},{"id":"heat","name":"الحرارة","meaning":"طاقة تنتقل بين جسمين بسبب اختلاف درجة حرارتهما.","example":"تنتقل الحرارة من الماء الدافئ إلى الملعقة الأبرد.","page":61,"aliases":[],"unit":"changes","lesson":"states","image":"images/heat.webp","audioText":"الحرارة. طاقة تنتقل بين جسمين بسبب اختلاف درجة حرارتهما. مثال. تنتقل الحرارة من الماء الدافئ إلى الملعقة الأبرد.","imageQuiz":true},{"id":"density","name":"الكثافة","meaning":"كتلة المادة الموجودة في وحدة من حجمها.","example":"الجليد أقل كثافة من الماء السائل لذلك يطفو.","page":61,"aliases":[],"unit":"changes","lesson":"states","image":"images/density.webp","audioText":"الكثافة. كتلة المادة الموجودة في وحدة من حجمها. مثال. الجليد أقل كثافة من الماء السائل لذلك يطفو.","imageQuiz":true},{"id":"compound","name":"المركّب","meaning":"مادة تتكون من اتحاد كيميائي بين عنصرين أو أكثر.","example":"الماء مركب من الهيدروجين والأكسجين.","page":68,"aliases":["المركب"],"unit":"changes","lesson":"compounds","image":"images/compound.webp","audioText":"المركّب. مادة تتكون من اتحاد كيميائي بين عنصرين أو أكثر. مثال. الماء مركب من الهيدروجين والأكسجين.","imageQuiz":true},{"id":"chemical-change","name":"التغير الكيميائي","meaning":"تغير تتكون فيه مادة جديدة تختلف في خصائصها عن المواد الأصلية.","example":"احتراق الخشب تغير كيميائي.","page":70,"aliases":["التفاعل الكيميائي"],"unit":"changes","lesson":"compounds","image":"images/chemical-change.webp","audioText":"التغير الكيميائي. تغير تتكون فيه مادة جديدة تختلف في خصائصها عن المواد الأصلية. مثال. احتراق الخشب تغير كيميائي.","imageQuiz":false},{"id":"reactants","name":"المواد المتفاعلة","meaning":"المواد الموجودة قبل بدء التفاعل الكيميائي.","example":"يتفاعل الهيدروجين والأكسجين لتكوين الماء.","page":71,"aliases":["المادة المتفاعلة"],"unit":"changes","lesson":"compounds","image":"images/reactants.webp","audioText":"المواد المتفاعلة. المواد الموجودة قبل بدء التفاعل الكيميائي. مثال. يتفاعل الهيدروجين والأكسجين لتكوين الماء.","imageQuiz":true},{"id":"products","name":"المواد الناتجة","meaning":"المواد الجديدة المتكونة بعد التفاعل الكيميائي.","example":"الماء مادة ناتجة في تفاعل تكوين الماء.","page":71,"aliases":["المادة الناتجة"],"unit":"changes","lesson":"compounds","image":"images/products.webp","audioText":"المواد الناتجة. المواد الجديدة المتكونة بعد التفاعل الكيميائي. مثال. الماء مادة ناتجة في تفاعل تكوين الماء.","imageQuiz":true},{"id":"chemical-equation","name":"المعادلة الكيميائية","meaning":"تمثيل بالرموز يبين المواد المتفاعلة والمواد الناتجة في تفاعل.","example":"توضح المعادلة تكوّن الماء من الهيدروجين والأكسجين.","page":71,"aliases":[],"unit":"changes","lesson":"compounds","image":"images/chemical-equation.webp","audioText":"المعادلة الكيميائية. تمثيل بالرموز يبين المواد المتفاعلة والمواد الناتجة في تفاعل. مثال. توضح المعادلة تكوّن الماء من الهيدروجين والأكسجين.","imageQuiz":true},{"id":"mass-conservation","name":"قانون حفظ الكتلة","meaning":"مجموع كتل المواد المتفاعلة يساوي مجموع كتل المواد الناتجة في نظام مغلق.","example":"تبقى الكتلة الكلية ثابتة في وعاء تفاعل مغلق.","page":71,"aliases":["حفظ الكتلة"],"unit":"changes","lesson":"compounds","image":"images/mass-conservation.webp","audioText":"قانون حفظ الكتلة. مجموع كتل المواد المتفاعلة يساوي مجموع كتل المواد الناتجة في نظام مغلق. مثال. تبقى الكتلة الكلية ثابتة في وعاء تفاعل مغلق.","imageQuiz":true},{"id":"precipitate","name":"الرواسب","meaning":"مواد صلبة قد تتكون عند تفاعل مواد مذابة في محاليل.","example":"ظهور مادة صلبة جديدة في المحلول قد يدل على تفاعل.","page":73,"aliases":["الراسب"],"unit":"changes","lesson":"compounds","image":"images/precipitate.webp","audioText":"الرواسب. مواد صلبة قد تتكون عند تفاعل مواد مذابة في محاليل. مثال. ظهور مادة صلبة جديدة في المحلول قد يدل على تفاعل.","imageQuiz":true},{"id":"rust","name":"صدأ الحديد","meaning":"مادة تتكون عند تفاعل الحديد مع الأكسجين بوجود الرطوبة.","example":"يتكون الصدأ على مسمار حديد رطب.","page":69,"aliases":["الصدأ"],"unit":"changes","lesson":"compounds","image":"images/rust.webp","audioText":"صدأ الحديد. مادة تتكون عند تفاعل الحديد مع الأكسجين بوجود الرطوبة. مثال. يتكون الصدأ على مسمار حديد رطب.","imageQuiz":true},{"id":"tarnish","name":"إزالة البريق","meaning":"فقدان سطح الفلز لمعانه بسبب تغير كيميائي.","example":"قد تصبح قطعة فلزية باهتة مع الزمن.","page":72,"aliases":["التشويه"],"unit":"changes","lesson":"compounds","image":"images/tarnish.webp","audioText":"إزالة البريق. فقدان سطح الفلز لمعانه بسبب تغير كيميائي. مثال. قد تصبح قطعة فلزية باهتة مع الزمن.","imageQuiz":true},{"id":"respiration","name":"التنفس الخلوي","meaning":"تفاعلات تحرر الطاقة من الغذاء داخل الخلايا.","example":"تستفيد الخلية من طاقة السكر في التنفس.","page":73,"aliases":["التنفس"],"unit":"changes","lesson":"compounds","image":"images/respiration.webp","audioText":"التنفس الخلوي. تفاعلات تحرر الطاقة من الغذاء داخل الخلايا. مثال. تستفيد الخلية من طاقة السكر في التنفس.","imageQuiz":true},{"id":"reproduction","name":"التكاثر","meaning":"إنتاج مخلوقات حية جديدة من النوع نفسه.","example":"تنتج النباتات أفرادًا جديدة.","page":82,"aliases":[],"unit":"reproduction","lesson":"reproduction","image":"images/reproduction.webp","audioText":"التكاثر. إنتاج مخلوقات حية جديدة من النوع نفسه. مثال. تنتج النباتات أفرادًا جديدة.","imageQuiz":false},{"id":"heredity","name":"المادة الوراثية","meaning":"مادة تحمل معلومات تحدد صفات المخلوق الحي وتنتقل إلى الأبناء.","example":"يحصل الأبناء على معلومات وراثية من آبائهم.","page":82,"aliases":[],"unit":"reproduction","lesson":"reproduction","image":"images/heredity.webp","audioText":"المادة الوراثية. مادة تحمل معلومات تحدد صفات المخلوق الحي وتنتقل إلى الأبناء. مثال. يحصل الأبناء على معلومات وراثية من آبائهم.","imageQuiz":false},{"id":"inherited-trait","name":"الصفة الوراثية","meaning":"صفة يمكن أن تنتقل من الآباء إلى الأبناء.","example":"قد يرث النبات لون أزهاره من أبويه.","page":82,"aliases":[],"unit":"reproduction","lesson":"reproduction","image":"images/inherited-trait.webp","audioText":"الصفة الوراثية. صفة يمكن أن تنتقل من الآباء إلى الأبناء. مثال. قد يرث النبات لون أزهاره من أبويه.","imageQuiz":false},{"id":"gamete","name":"المشيج","meaning":"خلية جنسية ذكرية أو أنثوية.","example":"البويضة مشيج مؤنث.","page":82,"aliases":[],"unit":"reproduction","lesson":"reproduction","image":"images/gamete.webp","audioText":"المشيج. خلية جنسية ذكرية أو أنثوية. مثال. البويضة مشيج مؤنث.","imageQuiz":false},{"id":"sperm","name":"الحيوان المنوي","meaning":"المشيج الذكري في الإنسان وكثير من الحيوانات.","example":"يتحد الحيوان المنوي مع البويضة عند الإخصاب.","page":82,"aliases":[],"unit":"reproduction","lesson":"reproduction","image":"images/sperm.webp","audioText":"الحيوان المنوي. المشيج الذكري في الإنسان وكثير من الحيوانات. مثال. يتحد الحيوان المنوي مع البويضة عند الإخصاب.","imageQuiz":true},{"id":"ovum","name":"البويضة","meaning":"المشيج الأنثوي الذي يمكن أن يتحد مع المشيج الذكري.","example":"تنتج الأنثى البويضات.","page":82,"aliases":[],"unit":"reproduction","lesson":"reproduction","image":"images/ovum.webp","audioText":"البويضة. المشيج الأنثوي الذي يمكن أن يتحد مع المشيج الذكري. مثال. تنتج الأنثى البويضات.","imageQuiz":true},{"id":"sexual","name":"التكاثر الجنسي","meaning":"إنتاج فرد جديد باتحاد مشيج مذكر ومشيج مؤنث.","example":"يحمل الصغير صفات من كلا الأبوين.","page":82,"aliases":[],"unit":"reproduction","lesson":"reproduction","image":"images/sexual.webp","audioText":"التكاثر الجنسي. إنتاج فرد جديد باتحاد مشيج مذكر ومشيج مؤنث. مثال. يحمل الصغير صفات من كلا الأبوين.","imageQuiz":false},{"id":"fertilization","name":"الإخصاب","meaning":"اتحاد المشيج المذكر بالمشيج المؤنث.","example":"ينتج عن الإخصاب بويضة مخصبة.","page":82,"aliases":[],"unit":"reproduction","lesson":"reproduction","image":"images/fertilization.webp","audioText":"الإخصاب. اتحاد المشيج المذكر بالمشيج المؤنث. مثال. ينتج عن الإخصاب بويضة مخصبة.","imageQuiz":true},{"id":"asexual","name":"التكاثر اللاجنسي","meaning":"إنتاج أفراد جديدة من أب واحد دون اتحاد مشيجين.","example":"تتكاثر البكتيريا لاجنسيًا بالانقسام.","page":83,"aliases":[],"unit":"reproduction","lesson":"reproduction","image":"images/asexual.webp","audioText":"التكاثر اللاجنسي. إنتاج أفراد جديدة من أب واحد دون اتحاد مشيجين. مثال. تتكاثر البكتيريا لاجنسيًا بالانقسام.","imageQuiz":true},{"id":"division","name":"الانقسام","meaning":"طريقة تكاثر لاجنسي تنقسم فيها خلية إلى خليتين.","example":"تنقسم خلية بكتيرية إلى خليتين.","page":84,"aliases":[],"unit":"reproduction","lesson":"reproduction","image":"images/division.webp","audioText":"الانقسام. طريقة تكاثر لاجنسي تنقسم فيها خلية إلى خليتين. مثال. تنقسم خلية بكتيرية إلى خليتين.","imageQuiz":true},{"id":"budding","name":"التبرعم","meaning":"طريقة تكاثر ينمو فيها بروز من جسم المخلوق ليكوّن فردًا جديدًا.","example":"تتكاثر الهيدرا بالتبرعم.","page":84,"aliases":[],"unit":"reproduction","lesson":"reproduction","image":"images/budding.webp","audioText":"التبرعم. طريقة تكاثر ينمو فيها بروز من جسم المخلوق ليكوّن فردًا جديدًا. مثال. تتكاثر الهيدرا بالتبرعم.","imageQuiz":true},{"id":"vegetative","name":"التكاثر الخضري","meaning":"تكاثر لاجنسي تنشأ فيه نباتات من أجزاء نباتية مثل الساق أو الجذر أو الورقة.","example":"يمكن أن ينمو نبات من برعم درنة بطاطس.","page":85,"aliases":[],"unit":"reproduction","lesson":"reproduction","image":"images/vegetative.webp","audioText":"التكاثر الخضري. تكاثر لاجنسي تنشأ فيه نباتات من أجزاء نباتية مثل الساق أو الجذر أو الورقة. مثال. يمكن أن ينمو نبات من برعم درنة بطاطس.","imageQuiz":true},{"id":"runner","name":"الساق الجارية","meaning":"ساق تمتد من النبات ويمكن أن تنمو عند عقدها جذور ونباتات جديدة.","example":"تنتج الفراولة نباتات جديدة بسيقان جارية.","page":85,"aliases":["السيقان الجارية"],"unit":"reproduction","lesson":"reproduction","image":"images/runner.webp","audioText":"الساق الجارية. ساق تمتد من النبات ويمكن أن تنمو عند عقدها جذور ونباتات جديدة. مثال. تنتج الفراولة نباتات جديدة بسيقان جارية.","imageQuiz":true},{"id":"life-cycle","name":"دورة الحياة","meaning":"مراحل نمو المخلوق الحي من بداية تكوّنه إلى بلوغه وتكاثره.","example":"تمر الفراشة بمراحل مختلفة خلال حياتها.","page":90,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/life-cycle.webp","audioText":"دورة الحياة. مراحل نمو المخلوق الحي من بداية تكوّنه إلى بلوغه وتكاثره. مثال. تمر الفراشة بمراحل مختلفة خلال حياتها.","imageQuiz":false},{"id":"metamorphosis","name":"التحوّل","meaning":"تغيرات مميزة في شكل الجسم خلال مراحل النمو.","example":"يتحول شكل الحشرة مع النمو.","page":90,"aliases":["التحول"],"unit":"reproduction","lesson":"life-cycles","image":"images/metamorphosis.webp","audioText":"التحوّل. تغيرات مميزة في شكل الجسم خلال مراحل النمو. مثال. يتحول شكل الحشرة مع النمو.","imageQuiz":false},{"id":"complete-metamorphosis","name":"التحول الكامل","meaning":"نمو الحشرة في أربع مراحل: بيضة ويرقة وعذراء وحشرة بالغة.","example":"تمر الفراشة بتحول كامل.","page":90,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/complete-metamorphosis.webp","audioText":"التحول الكامل. نمو الحشرة في أربع مراحل: بيضة ويرقة وعذراء وحشرة بالغة. مثال. تمر الفراشة بتحول كامل.","imageQuiz":true},{"id":"larva","name":"اليرقة","meaning":"مرحلة بعد الفقس لا تشبه فيها الحشرة شكلها البالغ.","example":"يرقة الفراشة تأكل الأوراق.","page":90,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/larva.webp","audioText":"اليرقة. مرحلة بعد الفقس لا تشبه فيها الحشرة شكلها البالغ. مثال. يرقة الفراشة تأكل الأوراق.","imageQuiz":true},{"id":"pupa","name":"العذراء","meaning":"مرحلة تتحول فيها تراكيب جسم بعض الحشرات قبل بلوغها.","example":"تتحول اليرقة إلى عذراء ثم فراشة.","page":90,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/pupa.webp","audioText":"العذراء. مرحلة تتحول فيها تراكيب جسم بعض الحشرات قبل بلوغها. مثال. تتحول اليرقة إلى عذراء ثم فراشة.","imageQuiz":true},{"id":"incomplete-metamorphosis","name":"التحول غير الكامل","meaning":"نمو الحشرة في ثلاث مراحل: بيضة وحورية وحشرة بالغة.","example":"تمر الجرادة بتحول غير كامل.","page":91,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/incomplete-metamorphosis.webp","audioText":"التحول غير الكامل. نمو الحشرة في ثلاث مراحل: بيضة وحورية وحشرة بالغة. مثال. تمر الجرادة بتحول غير كامل.","imageQuiz":true},{"id":"nymph","name":"الحورية","meaning":"حشرة صغيرة تشبه البالغة لكنها أصغر ولم تكتمل أجنحتها وتراكيب تكاثرها.","example":"تخرج حورية الجرادة من البيضة.","page":91,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/nymph.webp","audioText":"الحورية. حشرة صغيرة تشبه البالغة لكنها أصغر ولم تكتمل أجنحتها وتراكيب تكاثرها. مثال. تخرج حورية الجرادة من البيضة.","imageQuiz":true},{"id":"moulting","name":"الانسلاخ","meaning":"تخلص الحيوان من غطائه الخارجي ليتاح لجسمه النمو.","example":"تنسلخ الحورية عدة مرات قبل بلوغها.","page":91,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/moulting.webp","audioText":"الانسلاخ. تخلص الحيوان من غطائه الخارجي ليتاح لجسمه النمو. مثال. تنسلخ الحورية عدة مرات قبل بلوغها.","imageQuiz":true},{"id":"external-fertilization","name":"الإخصاب الخارجي","meaning":"اتحاد المشيجين خارج جسم الأنثى.","example":"يحدث الإخصاب الخارجي عند كثير من الأسماك في الماء.","page":92,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/external-fertilization.webp","audioText":"الإخصاب الخارجي. اتحاد المشيجين خارج جسم الأنثى. مثال. يحدث الإخصاب الخارجي عند كثير من الأسماك في الماء.","imageQuiz":true},{"id":"internal-fertilization","name":"الإخصاب الداخلي","meaning":"اتحاد المشيجين داخل جسم الأنثى.","example":"يحدث الإخصاب الداخلي في الطيور والثدييات.","page":93,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/internal-fertilization.webp","audioText":"الإخصاب الداخلي. اتحاد المشيجين داخل جسم الأنثى. مثال. يحدث الإخصاب الداخلي في الطيور والثدييات.","imageQuiz":true},{"id":"zygote","name":"اللاقحة","meaning":"الخلية الناتجة من اتحاد المشيج المذكر بالمشيج المؤنث.","example":"تبدأ اللاقحة بالانقسام والنمو.","page":94,"aliases":["البويضة المخصبة"],"unit":"reproduction","lesson":"life-cycles","image":"images/zygote.webp","audioText":"اللاقحة. الخلية الناتجة من اتحاد المشيج المذكر بالمشيج المؤنث. مثال. تبدأ اللاقحة بالانقسام والنمو.","imageQuiz":true},{"id":"embryo","name":"الجنين","meaning":"مخلوق حي في مراحل نموه الأولى قبل الفقس أو الولادة.","example":"ينمو جنين الدجاج داخل البيضة.","page":94,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/embryo.webp","audioText":"الجنين. مخلوق حي في مراحل نموه الأولى قبل الفقس أو الولادة. مثال. ينمو جنين الدجاج داخل البيضة.","imageQuiz":true},{"id":"yolk","name":"المُحّ","meaning":"مادة غذائية مخزنة في البيضة يستفيد منها الجنين.","example":"يتغذى جنين الدجاج من المح.","page":94,"aliases":["المح","صفار البيضة"],"unit":"reproduction","lesson":"life-cycles","image":"images/yolk.webp","audioText":"المُحّ. مادة غذائية مخزنة في البيضة يستفيد منها الجنين. مثال. يتغذى جنين الدجاج من المح.","imageQuiz":true},{"id":"petal","name":"البتلة","meaning":"جزء من الزهرة، يكون ملونًا في كثير من النباتات ويساعد على جذب الملقحات.","example":"تجذب بتلات الزهرة النحلة.","page":96,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/petal.webp","audioText":"البتلة. جزء من الزهرة، يكون ملونًا في كثير من النباتات ويساعد على جذب الملقحات. مثال. تجذب بتلات الزهرة النحلة.","imageQuiz":true},{"id":"sepal","name":"السبلة","meaning":"جزء غالبًا أخضر يحمي الزهرة وهي برعم.","example":"تحيط السبلات بقاعدة الزهرة.","page":96,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/sepal.webp","audioText":"السبلة. جزء غالبًا أخضر يحمي الزهرة وهي برعم. مثال. تحيط السبلات بقاعدة الزهرة.","imageQuiz":true},{"id":"stamen","name":"السداة","meaning":"الجزء الذكري في الزهرة وتنتج عنده حبوب اللقاح.","example":"تتكون السداة من خيط ومتك.","page":96,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/stamen.webp","audioText":"السداة. الجزء الذكري في الزهرة وتنتج عنده حبوب اللقاح. مثال. تتكون السداة من خيط ومتك.","imageQuiz":true},{"id":"anther","name":"المتك","meaning":"جزء من السداة تتكون فيه حبوب اللقاح.","example":"يحمل المتك حبوب اللقاح.","page":96,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/anther.webp","audioText":"المتك. جزء من السداة تتكون فيه حبوب اللقاح. مثال. يحمل المتك حبوب اللقاح.","imageQuiz":true},{"id":"filament","name":"الخيط","meaning":"جزء من السداة يحمل المتك.","example":"يرفع الخيط المتك في الزهرة.","page":96,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/filament.webp","audioText":"الخيط. جزء من السداة يحمل المتك. مثال. يرفع الخيط المتك في الزهرة.","imageQuiz":true},{"id":"carpel","name":"الكربلة","meaning":"الجزء الأنثوي في الزهرة ويضم الميسم والقلم والمبيض.","example":"توجد البويضات داخل مبيض الكربلة.","page":96,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/carpel.webp","audioText":"الكربلة. الجزء الأنثوي في الزهرة ويضم الميسم والقلم والمبيض. مثال. توجد البويضات داخل مبيض الكربلة.","imageQuiz":true},{"id":"stigma","name":"الميسم","meaning":"جزء يستقبل حبوب اللقاح في أعلى الكربلة.","example":"تلتصق حبوب اللقاح بالميسم.","page":96,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/stigma.webp","audioText":"الميسم. جزء يستقبل حبوب اللقاح في أعلى الكربلة. مثال. تلتصق حبوب اللقاح بالميسم.","imageQuiz":true},{"id":"style","name":"القلم","meaning":"جزء يصل الميسم بالمبيض في الكربلة.","example":"يمتد القلم بين الميسم والمبيض.","page":96,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/style.webp","audioText":"القلم. جزء يصل الميسم بالمبيض في الكربلة. مثال. يمتد القلم بين الميسم والمبيض.","imageQuiz":true},{"id":"ovary","name":"المبيض","meaning":"جزء من الكربلة توجد فيه البويضات.","example":"توجد البويضات داخل مبيض الزهرة.","page":96,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/ovary.webp","audioText":"المبيض. جزء من الكربلة توجد فيه البويضات. مثال. توجد البويضات داخل مبيض الزهرة.","imageQuiz":true},{"id":"pollination","name":"التلقيح","meaning":"انتقال حبوب اللقاح من المتك إلى ميسم زهرة مناسبة.","example":"تنقل النحلة حبوب اللقاح بين الأزهار.","page":96,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/pollination.webp","audioText":"التلقيح. انتقال حبوب اللقاح من المتك إلى ميسم زهرة مناسبة. مثال. تنقل النحلة حبوب اللقاح بين الأزهار.","imageQuiz":true},{"id":"pollen","name":"حبوب اللقاح","meaning":"حبيبات تحمل الخلايا الجنسية الذكرية في النباتات الزهرية.","example":"تلتصق حبوب اللقاح بجسم النحلة.","page":96,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/pollen.webp","audioText":"حبوب اللقاح. حبيبات تحمل الخلايا الجنسية الذكرية في النباتات الزهرية. مثال. تلتصق حبوب اللقاح بجسم النحلة.","imageQuiz":true},{"id":"pollinator","name":"الملقِّح","meaning":"وسيلة حية تنقل حبوب اللقاح بين الأزهار.","example":"النحلة من الملقحات.","page":96,"aliases":["الملقح","الملقحات"],"unit":"reproduction","lesson":"life-cycles","image":"images/pollinator.webp","audioText":"الملقِّح. وسيلة حية تنقل حبوب اللقاح بين الأزهار. مثال. النحلة من الملقحات.","imageQuiz":true},{"id":"nectar","name":"الرحيق","meaning":"سائل سكري تنتجه الأزهار ويجذب بعض الملقحات.","example":"تمتص النحلة الرحيق من الزهرة.","page":96,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/nectar.webp","audioText":"الرحيق. سائل سكري تنتجه الأزهار ويجذب بعض الملقحات. مثال. تمتص النحلة الرحيق من الزهرة.","imageQuiz":true},{"id":"self-pollination","name":"التلقيح الذاتي","meaning":"انتقال حبوب اللقاح إلى ميسم زهرة في النبات نفسه.","example":"قد تلقح الزهرة نفسها.","page":97,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/self-pollination.webp","audioText":"التلقيح الذاتي. انتقال حبوب اللقاح إلى ميسم زهرة في النبات نفسه. مثال. قد تلقح الزهرة نفسها.","imageQuiz":true},{"id":"cross-pollination","name":"التلقيح الخلطي","meaning":"انتقال حبوب اللقاح بين زهرتين على نباتين من النوع نفسه.","example":"تنقل النحلة اللقاح من نبات إلى آخر.","page":97,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/cross-pollination.webp","audioText":"التلقيح الخلطي. انتقال حبوب اللقاح بين زهرتين على نباتين من النوع نفسه. مثال. تنقل النحلة اللقاح من نبات إلى آخر.","imageQuiz":true},{"id":"seed","name":"البذرة","meaning":"تركيب يضم جنين نبات ومخزونًا غذائيًا وغلافًا يحميه.","example":"تنمو البذرة إلى نبتة عند توفر الظروف المناسبة.","page":97,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/seed.webp","audioText":"البذرة. تركيب يضم جنين نبات ومخزونًا غذائيًا وغلافًا يحميه. مثال. تنمو البذرة إلى نبتة عند توفر الظروف المناسبة.","imageQuiz":true},{"id":"fruit","name":"الثمرة","meaning":"جزء ينشأ غالبًا من مبيض الزهرة ويحتوي البذور ويحميها.","example":"داخل ثمرة القرع بذور.","page":97,"aliases":[],"unit":"reproduction","lesson":"life-cycles","image":"images/fruit.webp","audioText":"الثمرة. جزء ينشأ غالبًا من مبيض الزهرة ويحتوي البذور ويحميها. مثال. داخل ثمرة القرع بذور.","imageQuiz":true},{"id":"atmosphere","name":"الغلاف الجوي","meaning":"غطاء من الغازات يحيط بالأرض.","example":"نعيش في الجزء السفلي من الغلاف الجوي.","page":106,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/atmosphere.webp","audioText":"الغلاف الجوي. غطاء من الغازات يحيط بالأرض. مثال. نعيش في الجزء السفلي من الغلاف الجوي.","imageQuiz":true},{"id":"hydrosphere","name":"الغلاف المائي","meaning":"مياه الأرض في حالاتها الصلبة والسائلة والغازية.","example":"المحيطات والجليديات من الغلاف المائي.","page":106,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/hydrosphere.webp","audioText":"الغلاف المائي. مياه الأرض في حالاتها الصلبة والسائلة والغازية. مثال. المحيطات والجليديات من الغلاف المائي.","imageQuiz":true},{"id":"biosphere","name":"الغلاف الحيوي","meaning":"الأجزاء من الأرض التي توجد فيها الحياة.","example":"تعيش المخلوقات في أجزاء من اليابسة والماء والهواء.","page":107,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/biosphere.webp","audioText":"الغلاف الحيوي. الأجزاء من الأرض التي توجد فيها الحياة. مثال. تعيش المخلوقات في أجزاء من اليابسة والماء والهواء.","imageQuiz":true},{"id":"crust","name":"القشرة الأرضية","meaning":"الطبقة الصخرية الخارجية للأرض.","example":"نعيش على القشرة الأرضية.","page":106,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/crust.webp","audioText":"القشرة الأرضية. الطبقة الصخرية الخارجية للأرض. مثال. نعيش على القشرة الأرضية.","imageQuiz":true},{"id":"mantle","name":"الوشاح","meaning":"طبقة من صخور حارة تحت القشرة الأرضية.","example":"يقع الوشاح بين القشرة واللب.","page":106,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/mantle.webp","audioText":"الوشاح. طبقة من صخور حارة تحت القشرة الأرضية. مثال. يقع الوشاح بين القشرة واللب.","imageQuiz":true},{"id":"lithosphere","name":"الغلاف الصخري","meaning":"القشرة الأرضية والجزء العلوي الصلب من الوشاح.","example":"ينقسم الغلاف الصخري إلى صفائح.","page":106,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/lithosphere.webp","audioText":"الغلاف الصخري. القشرة الأرضية والجزء العلوي الصلب من الوشاح. مثال. ينقسم الغلاف الصخري إلى صفائح.","imageQuiz":true},{"id":"asthenosphere","name":"الطبقة اللدنة","meaning":"منطقة من الوشاح تتصرف صخورها الحارة بلدونة وتتحرك فوقها الصفائح.","example":"تتحرك الصفائح ببطء فوق الطبقة اللدنة.","page":106,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/asthenosphere.webp","audioText":"الطبقة اللدنة. منطقة من الوشاح تتصرف صخورها الحارة بلدونة وتتحرك فوقها الصفائح. مثال. تتحرك الصفائح ببطء فوق الطبقة اللدنة.","imageQuiz":true},{"id":"core","name":"اللب","meaning":"الجزء المركزي من الأرض، ويضم اللب الخارجي والداخلي.","example":"يقع اللب في مركز الأرض.","page":107,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/core.webp","audioText":"اللب. الجزء المركزي من الأرض، ويضم اللب الخارجي والداخلي. مثال. يقع اللب في مركز الأرض.","imageQuiz":true},{"id":"outer-core","name":"اللب الخارجي","meaning":"نطاق سائل يحيط باللب الداخلي.","example":"اللب الخارجي سائل.","page":107,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/outer-core.webp","audioText":"اللب الخارجي. نطاق سائل يحيط باللب الداخلي. مثال. اللب الخارجي سائل.","imageQuiz":true},{"id":"inner-core","name":"اللب الداخلي","meaning":"نطاق صلب في مركز الأرض.","example":"اللب الداخلي صلب.","page":107,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/inner-core.webp","audioText":"اللب الداخلي. نطاق صلب في مركز الأرض. مثال. اللب الداخلي صلب.","imageQuiz":true},{"id":"tectonic-plate","name":"الصفيحة الأرضية","meaning":"لوح صخري ضخم يشكل جزءًا من الغلاف الصخري.","example":"تتحرك الصفيحة العربية ببطء.","page":108,"aliases":["الصفائح الأرضية"],"unit":"earth","lesson":"earth-structure","image":"images/tectonic-plate.webp","audioText":"الصفيحة الأرضية. لوح صخري ضخم يشكل جزءًا من الغلاف الصخري. مثال. تتحرك الصفيحة العربية ببطء.","imageQuiz":true},{"id":"fault","name":"الصدع","meaning":"كسر في صخور القشرة تتحرك على جانبيه كتل صخرية.","example":"تحدث زلازل كثيرة قرب الصدوع.","page":108,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/fault.webp","audioText":"الصدع. كسر في صخور القشرة تتحرك على جانبيه كتل صخرية. مثال. تحدث زلازل كثيرة قرب الصدوع.","imageQuiz":true},{"id":"earthquake","name":"الزلزال","meaning":"اهتزاز للقشرة الأرضية بسبب تحرر طاقة في باطن الأرض.","example":"تهتز الأرض عند حدوث زلزال.","page":109,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/earthquake.webp","audioText":"الزلزال. اهتزاز للقشرة الأرضية بسبب تحرر طاقة في باطن الأرض. مثال. تهتز الأرض عند حدوث زلزال.","imageQuiz":false},{"id":"seismic-waves","name":"الموجات الزلزالية","meaning":"موجات تنقل طاقة الزلزال من بؤرته إلى الجهات المحيطة.","example":"تنتشر الموجات من موقع بدء الزلزال.","page":110,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/seismic-waves.webp","audioText":"الموجات الزلزالية. موجات تنقل طاقة الزلزال من بؤرته إلى الجهات المحيطة. مثال. تنتشر الموجات من موقع بدء الزلزال.","imageQuiz":true},{"id":"focus","name":"بؤرة الزلزال","meaning":"الموضع داخل الأرض الذي يبدأ عنده الزلزال.","example":"تنتشر الموجات الزلزالية من البؤرة.","page":110,"aliases":["البؤرة"],"unit":"earth","lesson":"earth-structure","image":"images/focus.webp","audioText":"بؤرة الزلزال. الموضع داخل الأرض الذي يبدأ عنده الزلزال. مثال. تنتشر الموجات الزلزالية من البؤرة.","imageQuiz":true},{"id":"epicenter","name":"المركز السطحي","meaning":"نقطة على سطح الأرض تقع فوق بؤرة الزلزال مباشرة.","example":"المركز السطحي فوق البؤرة.","page":110,"aliases":["المركز السطحي للزلزال"],"unit":"earth","lesson":"earth-structure","image":"images/epicenter.webp","audioText":"المركز السطحي. نقطة على سطح الأرض تقع فوق بؤرة الزلزال مباشرة. مثال. المركز السطحي فوق البؤرة.","imageQuiz":true},{"id":"seismometer","name":"السيزموميتر","meaning":"جهاز يرصد اهتزازات الأرض والموجات الزلزالية.","example":"تسجل محطات الرصد الموجات بأجهزة خاصة.","page":110,"aliases":["مقياس الزلازل"],"unit":"earth","lesson":"earth-structure","image":"images/seismometer.webp","audioText":"السيزموميتر. جهاز يرصد اهتزازات الأرض والموجات الزلزالية. مثال. تسجل محطات الرصد الموجات بأجهزة خاصة.","imageQuiz":true},{"id":"magnitude","name":"قوة الزلزال","meaning":"مقياس يرتبط بمقدار الطاقة المتحررة أثناء الزلزال.","example":"الزلزال الأقوى يحرر طاقة أكبر.","page":112,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/magnitude.webp","audioText":"قوة الزلزال. مقياس يرتبط بمقدار الطاقة المتحررة أثناء الزلزال. مثال. الزلزال الأقوى يحرر طاقة أكبر.","imageQuiz":true},{"id":"richter","name":"مقياس ريختر","meaning":"مقياس عددي يستخدم لوصف مقدار الزلازل.","example":"يذكر الكتاب درجات الزلازل على مقياس ريختر.","page":112,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/richter.webp","audioText":"مقياس ريختر. مقياس عددي يستخدم لوصف مقدار الزلازل. مثال. يذكر الكتاب درجات الزلازل على مقياس ريختر.","imageQuiz":true},{"id":"tsunami","name":"التسونامي","meaning":"أمواج بحرية كبيرة قد تنتج من تحرك مفاجئ لقاع البحر.","example":"قد يحدث تسونامي بعد زلزال قوي تحت البحر.","page":112,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/tsunami.webp","audioText":"التسونامي. أمواج بحرية كبيرة قد تنتج من تحرك مفاجئ لقاع البحر. مثال. قد يحدث تسونامي بعد زلزال قوي تحت البحر.","imageQuiz":true},{"id":"volcano","name":"البركان","meaning":"فتحة في القشرة تخرج منها مواد منصهرة وغازات ورماد.","example":"تندفع المواد من فتحة البركان.","page":113,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/volcano.webp","audioText":"البركان. فتحة في القشرة تخرج منها مواد منصهرة وغازات ورماد. مثال. تندفع المواد من فتحة البركان.","imageQuiz":false},{"id":"magma","name":"الماجما","meaning":"صخور منصهرة أو شبه منصهرة توجد تحت سطح الأرض.","example":"تتجمع الماجما في خزان تحت البركان.","page":108,"aliases":["الصهارة"],"unit":"earth","lesson":"earth-structure","image":"images/magma.webp","audioText":"الماجما. صخور منصهرة أو شبه منصهرة توجد تحت سطح الأرض. مثال. تتجمع الماجما في خزان تحت البركان.","imageQuiz":true},{"id":"lava","name":"اللابة","meaning":"الماجما بعد خروجها إلى سطح الأرض.","example":"تجري اللابة على منحدر البركان.","page":113,"aliases":["الحمم البركانية"],"unit":"earth","lesson":"earth-structure","image":"images/lava.webp","audioText":"اللابة. الماجما بعد خروجها إلى سطح الأرض. مثال. تجري اللابة على منحدر البركان.","imageQuiz":true},{"id":"crater","name":"الفوهة البركانية","meaning":"منخفض أو فتحة واسعة قرب قمة البركان.","example":"قد تتسع الفوهة في قمة البركان.","page":113,"aliases":["فوهة البركان"],"unit":"earth","lesson":"earth-structure","image":"images/crater.webp","audioText":"الفوهة البركانية. منخفض أو فتحة واسعة قرب قمة البركان. مثال. قد تتسع الفوهة في قمة البركان.","imageQuiz":true},{"id":"active-volcano","name":"البركان النشط","meaning":"بركان تثور منه المواد حاليًا أو ثار حديثًا وفق وصف الدرس.","example":"تخرج اللابة من بركان نشط.","page":113,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/active-volcano.webp","audioText":"البركان النشط. بركان تثور منه المواد حاليًا أو ثار حديثًا وفق وصف الدرس. مثال. تخرج اللابة من بركان نشط.","imageQuiz":true},{"id":"dormant-volcano","name":"البركان الساكن","meaning":"بركان توقف عن الثوران وقد يثور من جديد.","example":"يمكن أن يعود البركان الساكن إلى النشاط.","page":113,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/dormant-volcano.webp","audioText":"البركان الساكن. بركان توقف عن الثوران وقد يثور من جديد. مثال. يمكن أن يعود البركان الساكن إلى النشاط.","imageQuiz":true},{"id":"extinct-volcano","name":"البركان الخامد","meaning":"بركان توقف عن الثوران ولا يتوقع أن يثور مجددًا وفق وصف الدرس.","example":"البركان الخامد مختلف عن الساكن.","page":113,"aliases":[],"unit":"earth","lesson":"earth-structure","image":"images/extinct-volcano.webp","audioText":"البركان الخامد. بركان توقف عن الثوران ولا يتوقع أن يثور مجددًا وفق وصف الدرس. مثال. البركان الخامد مختلف عن الساكن.","imageQuiz":true},{"id":"lava-field","name":"الحَرّة","meaning":"مساحة من الأرض تغطيها صخور بركانية داكنة.","example":"توجد حرات في شبه الجزيرة العربية.","page":113,"aliases":["الحرة","الحرات"],"unit":"earth","lesson":"earth-structure","image":"images/lava-field.webp","audioText":"الحَرّة. مساحة من الأرض تغطيها صخور بركانية داكنة. مثال. توجد حرات في شبه الجزيرة العربية.","imageQuiz":true},{"id":"weathering","name":"التجوية","meaning":"تفتيت الصخور أو تغيرها في موضعها بفعل عوامل مختلفة.","example":"قد يكسر الجليد صخرًا متشققًا.","page":118,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/weathering.webp","audioText":"التجوية. تفتيت الصخور أو تغيرها في موضعها بفعل عوامل مختلفة. مثال. قد يكسر الجليد صخرًا متشققًا.","imageQuiz":false},{"id":"physical-weathering","name":"التجوية الفيزيائية","meaning":"تفتيت الصخر دون تغيير تركيبه الكيميائي.","example":"توسع جذور النبات شقًا في صخر.","page":118,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/physical-weathering.webp","audioText":"التجوية الفيزيائية. تفتيت الصخر دون تغيير تركيبه الكيميائي. مثال. توسع جذور النبات شقًا في صخر.","imageQuiz":true},{"id":"chemical-weathering","name":"التجوية الكيميائية","meaning":"تغير معادن الصخور وتركيبها بفعل تفاعلات كيميائية.","example":"قد تذيب مياه محملة بمواد حمضية بعض الصخور.","page":119,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/chemical-weathering.webp","audioText":"التجوية الكيميائية. تغير معادن الصخور وتركيبها بفعل تفاعلات كيميائية. مثال. قد تذيب مياه محملة بمواد حمضية بعض الصخور.","imageQuiz":true},{"id":"acid-rain","name":"الأمطار الحمضية","meaning":"مطر ازدادت حموضته بسبب ملوثات في الهواء.","example":"قد تؤدي الأمطار الحمضية إلى تآكل بعض المباني.","page":119,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/acid-rain.webp","audioText":"الأمطار الحمضية. مطر ازدادت حموضته بسبب ملوثات في الهواء. مثال. قد تؤدي الأمطار الحمضية إلى تآكل بعض المباني.","imageQuiz":true},{"id":"erosion","name":"التعرية","meaning":"نقل نواتج التجوية من مكان إلى آخر.","example":"ينقل النهر فتات الصخور.","page":120,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/erosion.webp","audioText":"التعرية. نقل نواتج التجوية من مكان إلى آخر. مثال. ينقل النهر فتات الصخور.","imageQuiz":true},{"id":"glacier","name":"الجليديات","meaning":"كتل كبيرة من الجليد تتحرك ببطء.","example":"تنقل الجليديات صخورًا في أثناء حركتها.","page":120,"aliases":["الكتل الجليدية"],"unit":"earth","lesson":"weathering","image":"images/glacier.webp","audioText":"الجليديات. كتل كبيرة من الجليد تتحرك ببطء. مثال. تنقل الجليديات صخورًا في أثناء حركتها.","imageQuiz":true},{"id":"deposition","name":"الترسيب","meaning":"استقرار المواد المنقولة بالماء أو الرياح أو الجليد.","example":"تستقر الرمال عندما تهدأ الرياح.","page":121,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/deposition.webp","audioText":"الترسيب. استقرار المواد المنقولة بالماء أو الرياح أو الجليد. مثال. تستقر الرمال عندما تهدأ الرياح.","imageQuiz":true},{"id":"sediment","name":"الرسوبيات","meaning":"فتات صخر وتربة ومواد تنقلها عوامل التعرية ثم قد تترسب.","example":"يحمل الماء رسوبيات دقيقة.","page":121,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/sediment.webp","audioText":"الرسوبيات. فتات صخر وتربة ومواد تنقلها عوامل التعرية ثم قد تترسب. مثال. يحمل الماء رسوبيات دقيقة.","imageQuiz":true},{"id":"delta","name":"الدلتا","meaning":"منطقة تتراكم فيها رسوبيات عند مصب نهر وتتفرع فيها مجاريه.","example":"تترسب مواد النهر عند مصبه.","page":121,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/delta.webp","audioText":"الدلتا. منطقة تتراكم فيها رسوبيات عند مصب نهر وتتفرع فيها مجاريه. مثال. تترسب مواد النهر عند مصبه.","imageQuiz":true},{"id":"sandbar","name":"الحاجز الرملي","meaning":"تجمع ممتد من الرمل ترسبه المياه قرب الساحل.","example":"قد يمتد الحاجز الرملي بمحاذاة الشاطئ.","page":122,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/sandbar.webp","audioText":"الحاجز الرملي. تجمع ممتد من الرمل ترسبه المياه قرب الساحل. مثال. قد يمتد الحاجز الرملي بمحاذاة الشاطئ.","imageQuiz":true},{"id":"barrier-island","name":"الجزر الحديّة","meaning":"جزر رملية ممتدة قرب الساحل تساعد على حمايته من الأمواج.","example":"تفصل بعض الجزر الحدية البحر عن مناطق ساحلية.","page":122,"aliases":["الجزر الحدية"],"unit":"earth","lesson":"weathering","image":"images/barrier-island.webp","audioText":"الجزر الحديّة. جزر رملية ممتدة قرب الساحل تساعد على حمايته من الأمواج. مثال. تفصل بعض الجزر الحدية البحر عن مناطق ساحلية.","imageQuiz":true},{"id":"dune","name":"الكثبان الرملية","meaning":"تلال من الرمل تنقلها الرياح وتراكمها.","example":"قد تتحرك الكثبان مع الرياح.","page":123,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/dune.webp","audioText":"الكثبان الرملية. تلال من الرمل تنقلها الرياح وتراكمها. مثال. قد تتحرك الكثبان مع الرياح.","imageQuiz":true},{"id":"soil","name":"التربة","meaning":"خليط من فتات الصخور ومواد عضوية ومخلوقات حية وماء وهواء.","example":"تنمو جذور النبات في التربة.","page":124,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/soil.webp","audioText":"التربة. خليط من فتات الصخور ومواد عضوية ومخلوقات حية وماء وهواء. مثال. تنمو جذور النبات في التربة.","imageQuiz":true},{"id":"organic-matter","name":"المواد العضوية","meaning":"مواد مصدرها مخلوقات حية أو بقاياها.","example":"تضيف أوراق النبات المتحللة مواد عضوية للتربة.","page":124,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/organic-matter.webp","audioText":"المواد العضوية. مواد مصدرها مخلوقات حية أو بقاياها. مثال. تضيف أوراق النبات المتحللة مواد عضوية للتربة.","imageQuiz":true},{"id":"soil-horizon","name":"نطاق التربة","meaning":"طبقة من طبقات التربة لها خصائص تميزها.","example":"يمكن ملاحظة النطاقات في مقطع للتربة.","page":125,"aliases":["نطاقات التربة"],"unit":"earth","lesson":"weathering","image":"images/soil-horizon.webp","audioText":"نطاق التربة. طبقة من طبقات التربة لها خصائص تميزها. مثال. يمكن ملاحظة النطاقات في مقطع للتربة.","imageQuiz":true},{"id":"humus","name":"الدبال","meaning":"مواد عضوية متحللة في التربة تساعد على الاحتفاظ بالماء وتوفر مغذيات.","example":"التربة الداكنة قد تكون غنية بالدبال.","page":125,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/humus.webp","audioText":"الدبال. مواد عضوية متحللة في التربة تساعد على الاحتفاظ بالماء وتوفر مغذيات. مثال. التربة الداكنة قد تكون غنية بالدبال.","imageQuiz":true},{"id":"topsoil","name":"التربة السطحية","meaning":"التربة في النطاق أ، وتنمو فيها معظم الجذور وتكثر فيها المغذيات.","example":"تحتاج التربة السطحية إلى الحماية من الانجراف.","page":125,"aliases":["النطاق أ"],"unit":"earth","lesson":"weathering","image":"images/topsoil.webp","audioText":"التربة السطحية. التربة في النطاق أ، وتنمو فيها معظم الجذور وتكثر فيها المغذيات. مثال. تحتاج التربة السطحية إلى الحماية من الانجراف.","imageQuiz":true},{"id":"subsoil","name":"التربة تحت السطحية","meaning":"النطاق ب تحت التربة السطحية، ويحتوي عادة دبالًا أقل ومواد صخرية أكثر.","example":"قد تصل بعض جذور النبات إلى النطاق ب.","page":125,"aliases":["النطاق ب"],"unit":"earth","lesson":"weathering","image":"images/subsoil.webp","audioText":"التربة تحت السطحية. النطاق ب تحت التربة السطحية، ويحتوي عادة دبالًا أقل ومواد صخرية أكثر. مثال. قد تصل بعض جذور النبات إلى النطاق ب.","imageQuiz":true},{"id":"parent-material","name":"النطاق ج","meaning":"نطاق يحتوي قطعًا صخرية كبيرة فوق الصخور غير المتجواة.","example":"يوجد النطاق ج أسفل النطاق ب.","page":125,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/parent-material.webp","audioText":"النطاق ج. نطاق يحتوي قطعًا صخرية كبيرة فوق الصخور غير المتجواة. مثال. يوجد النطاق ج أسفل النطاق ب.","imageQuiz":true},{"id":"pollution","name":"التلوث","meaning":"إضافة مواد ضارة إلى التربة أو الماء أو الهواء.","example":"قد تلوث النفايات الكيميائية التربة.","page":127,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/pollution.webp","audioText":"التلوث. إضافة مواد ضارة إلى التربة أو الماء أو الهواء. مثال. قد تلوث النفايات الكيميائية التربة.","imageQuiz":true},{"id":"soil-conservation","name":"حفظ التربة","meaning":"حماية التربة والمحافظة على خصوبتها وتقليل فقدها.","example":"تساعد زراعة الأشجار على حفظ التربة.","page":128,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/soil-conservation.webp","audioText":"حفظ التربة. حماية التربة والمحافظة على خصوبتها وتقليل فقدها. مثال. تساعد زراعة الأشجار على حفظ التربة.","imageQuiz":true},{"id":"fertilizing","name":"التسميد","meaning":"إضافة مغذيات إلى التربة لتعويض ما استهلكته النباتات.","example":"يضاف السماد المناسب لتحسين تغذية النبات.","page":128,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/fertilizing.webp","audioText":"التسميد. إضافة مغذيات إلى التربة لتعويض ما استهلكته النباتات. مثال. يضاف السماد المناسب لتحسين تغذية النبات.","imageQuiz":true},{"id":"crop-rotation","name":"الدورة الزراعية","meaning":"زراعة محاصيل مختلفة بالتتابع في الأرض نفسها.","example":"تزرع البقوليات بين مواسم محاصيل أخرى.","page":128,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/crop-rotation.webp","audioText":"الدورة الزراعية. زراعة محاصيل مختلفة بالتتابع في الأرض نفسها. مثال. تزرع البقوليات بين مواسم محاصيل أخرى.","imageQuiz":true},{"id":"strip-cropping","name":"الأشرطة المتبادلة","meaning":"زراعة أشرطة من نباتات مختلفة لتقليل انجراف التربة.","example":"تزرع أعشاب بين صفوف محاصيل.","page":128,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/strip-cropping.webp","audioText":"الأشرطة المتبادلة. زراعة أشرطة من نباتات مختلفة لتقليل انجراف التربة. مثال. تزرع أعشاب بين صفوف محاصيل.","imageQuiz":true},{"id":"contour-plowing","name":"الحراثة الكنتورية","meaning":"حراثة الأرض عبر المنحدر على خطوط متقاربة الارتفاع لتقليل جريان الماء.","example":"تتبع الأخاديد شكل المنحدر بدل النزول معه.","page":128,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/contour-plowing.webp","audioText":"الحراثة الكنتورية. حراثة الأرض عبر المنحدر على خطوط متقاربة الارتفاع لتقليل جريان الماء. مثال. تتبع الأخاديد شكل المنحدر بدل النزول معه.","imageQuiz":true},{"id":"terrace","name":"المصاطب","meaning":"مسطحات زراعية متدرجة تقطع في التلال لتبطئ جريان المياه.","example":"تزرع النباتات على درجات مستوية.","page":128,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/terrace.webp","audioText":"المصاطب. مسطحات زراعية متدرجة تقطع في التلال لتبطئ جريان المياه. مثال. تزرع النباتات على درجات مستوية.","imageQuiz":true},{"id":"windbreak","name":"مصدات الرياح","meaning":"صفوف أشجار أو حواجز تقلل سرعة الرياح وتحمي التربة.","example":"تزرع أشجار طويلة حول المزرعة.","page":128,"aliases":[],"unit":"earth","lesson":"weathering","image":"images/windbreak.webp","audioText":"مصدات الرياح. صفوف أشجار أو حواجز تقلل سرعة الرياح وتحمي التربة. مثال. تزرع أشجار طويلة حول المزرعة.","imageQuiz":true},{"id":"boiling","name":"الغليان","meaning":"تحول السائل إلى غاز في جميع أجزائه عند درجة غليانه.","example":"تتكون فقاعات بخار في الماء المغلي.","page":62,"aliases":[],"unit":"changes","lesson":"states","image":"images/boiling.webp","audioText":"الغليان. تحول السائل إلى غاز في جميع أجزائه عند درجة غليانه. مثال. تتكون فقاعات بخار في الماء المغلي.","imageQuiz":true}],"grade":5,"gradeLabel":"الصف الخامس","mediaPrefix":"g5-"};
